    ('hv2', '31', 'Person 4', null::jsonb, 3, null::jsonb, 3),
    ('hv3', '32', 'Die Firma hat zurzeit', '[{"key": "A", "text": "mehr Ersthelfer als gesetzlich vorgeschrieben."}, {"key": "B", "text": "so viele Ersthelfer wie gesetzlich vorgeschrieben."}, {"key": "C", "text": "weniger Ersthelfer als gesetzlich vorgeschrieben."}]'::jsonb, 3, null::jsonb, 0),
    ('hv3', '33', 'Die Ausbildung zum Ersthelfer', '[{"key": "A", "text": "ist kostenfrei."}, {"key": "B", "text": "ist nur beim Malteser Hilfsdienst erlaubt."}, {"key": "C", "text": "zählt voll zur Arbeitszeit."}]'::jsonb, 3, null::jsonb, 1),
    ('hv3', '34', 'Wer sich anmelden möchte,', '[{"key": "A", "text": "kann sich an das Personalbüro wenden."}, {"key": "B", "text": "muss dem Arbeitgeber eine Bescheinigung vorlegen."}, {"key": "C", "text": "sollte dies spätestens zwei Wochen vor Kursbeginn tun."}]'::jsonb, 3, null::jsonb, 2),
    ('hv3', '35', 'Murat', '[{"key": "A", "text": "kann ohne Lehrgang Ersthelfer werden, wenn er sein Ausbildungszeugnis vorlegt."}, {"key": "B", "text": "muss den kompletten Erste-Hilfe-Kurs wiederholen."}, {"key": "C", "text": "darf auf keinen Fall als Ersthelfer arbeiten."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '36', 'Andrea', '[{"key": "A", "text": "kann den geplanten Termin nicht einhalten."}, {"key": "B", "text": "möchte sich Montag wieder melden."}, {"key": "C", "text": "trifft einen Vertreter zum Arbeitsfrühstück."}]'::jsonb, 3, null::jsonb, 0),
    ('hv4', '37', 'Frau Plassberg', '[{"key": "A", "text": "möchte eine Steuerprüfung auswerten."}, {"key": "B", "text": "möchte die neue Werbekampagne diskutieren."}, {"key": "C", "text": "möchte über die Dienstreise sprechen."}]'::jsonb, 3, null::jsonb, 1),
    ('hv4', '38', 'Daniela Schöller', '[{"key": "A", "text": "bittet um heutige Abholung der Ware."}, {"key": "B", "text": "braucht die Lieferung dringend."}, {"key": "C", "text": "hat den Eilzuschlag bezahlt."}]'::jsonb, 3, null::jsonb, 2),
    ('hv4', '39', 'Herr Lattermann', '[{"key": "A", "text": "bekommt eine Maschine aus Hamburg."}, {"key": "B", "text": "bestätigt den Empfang der Maschine."}, {"key": "C", "text": "liefert eine Maschine nach Dresden."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '40', 'Frau Bernhardt', '[{"key": "A", "text": "hat Änderungswünsche für die Homepage."}, {"key": "B", "text": "meldet sich bei ihrer Sekretärin."}, {"key": "C", "text": "möchte die Garantie verlängern."}]'::jsonb, 3, null::jsonb, 4),
    ('hvs', '41', 'Dokumentieren Sie die Kundenanfrage:', null::jsonb, 0, '{"points": ["Anruferin und Firma (Adriane Schmid, Autovermietung Klein)", "Rückrufnummer (0173 721 572 6)", "Einzelheiten des Angebots (Mittelklassewagen für 99 Euro pro Tag)", "Bedingungen (Vollgetankt abgeben oder kostenpflichtig, Versicherung regeln)", "Zu erledigen (Rückruf, ob das Angebot angenommen wird)"]}'::jsonb, 0),
    ('sb1', '46', '… Ausbildungskonzept Ihrer Hotelkette informiert und bin (46), in Ihrem Haus vielfältige Einblicke in die …', null::jsonb, 0.5, null::jsonb, 0),
    ('sb1', '47', '… Voraussetzung mit und interessiere mich (47) die Abläufe in der Hotelverwaltung. Ein Praktikum in der …', null::jsonb, 0.5, null::jsonb, 1),
    ('sb1', '48', '… Hotelbranche möchte ich deshalb absolvieren, (48) ich nicht nur im Umgang mit Menschen, …', null::jsonb, 0.5, null::jsonb, 2),
    ('sb1', '49', '… ich nicht nur im Umgang mit Menschen, (49) auch im Planen und Organisieren meine großen …', null::jsonb, 0.5, null::jsonb, 3),
    ('sb1', '50', '… praktische Erfahrung weiter vertiefen zu können, (50) mir dann mit meiner Berufswahl endgültig sicher zu …', null::jsonb, 0.5, null::jsonb, 4),
    ('sb1', '51', '… Berufswahl endgültig sicher zu sein. (51) überzeuge ich Sie in einem persönlichen Gespräch. Über eine …', null::jsonb, 0.5, null::jsonb, 5),
    ('sb2', '52', '… Vertriebsmitarbeiters entschieden wir uns für (52) von zwei Kaffeevollautomaten für unsere Krankenhauskantine. …', '[{"key": "A", "text": "einen Auftrag"}, {"key": "B", "text": "eine Bestellung"}, {"key": "C", "text": "eine Anforderung"}]'::jsonb, 0.5, null::jsonb, 0),
    ('sb2', '53', '… Auftragserteilung erfolgte in KW 12. Wir (53) eine Auftragsbestätigung mit Liefertermin in KW 16. …', '[{"key": "A", "text": "bekommen danach"}, {"key": "B", "text": "bestellten dann"}, {"key": "C", "text": "erhielten daraufhin"}]'::jsonb, 0.5, null::jsonb, 1),
    ('sb2', '54', '… Liefertermin in KW 16. (54) der Lieferfrist haben wir Sie telefonisch mehrmals …', '[{"key": "A", "text": "Vor Beginn"}, {"key": "B", "text": "Nach Ablauf"}, {"key": "C", "text": "Während"}]'::jsonb, 0.5, null::jsonb, 2),
    ('sb2', '55', '… dringend benötigen. (55) wir uns in KW 18 und haben die Lieferung immer noch nicht erhalten. …', '[{"key": "A", "text": "Mittlerweile befinden"}, {"key": "B", "text": "Früher waren"}, {"key": "C", "text": "Bald sind"}]'::jsonb, 0.5, null::jsonb, 3),
    ('sb2', '56', '… Sollte die Ware bis dahin (56) sein, machen wir von unserem Widerrufsrecht Gebrauch …', '[{"key": "A", "text": "nicht eingetroffen"}, {"key": "B", "text": "beschädigt geliefert"}, {"key": "C", "text": "zurückgeschickt"}]'::jsonb, 0.5, null::jsonb, 4),
    ('sb2', '57', '… Bitte schicken Sie uns umgehend eine (57). Mit freundlichen Grüßen Eva Al Hossan', '[{"key": "A", "text": "telefonische Zusage"}, {"key": "B", "text": "neue Rechnung"}, {"key": "C", "text": "schriftliche Stellungnahme"}]'::jsonb, 0.5, null::jsonb, 5)
) as v(section_id, item_id, text, options, points, meta, sort)
