insert into sections (test_id, section_id, "group", title, minutes, instruction, format, config, sort)
select t.id, v.section_id, v.grp, v.title, v.minutes, v.instruction, v.format, v.config, v.sort
from (values
    ('lv1', 'Lesen', 'Lesen, Teil 1', 10, 'Lesen Sie die Aufgaben 1–5 und die Informationen a–h. Welche Information passt zu welcher Situation?', 'matching', '{"bank": [{"key": "A", "text": "Achtung Kündigung: Das Arbeitsrecht unterscheidet zwischen personenbedingter, betriebsbedingter und verhaltensbedingter Beendigung des Arbeitsverhältnisses. Lesen Sie hier alle Informationen darüber, aus welchen Gründen der Arbeitgeber berechtigt ist zu kündigen."}, {"key": "B", "text": "Automobilbranche boomt nach wie vor: Vor allem im Südwesten Deutschlands können sich die Menschen weiterhin auf sichere und gut bezahlte Anstellungen in der Automobilindustrie verlassen. Warum lohnt es sich, bei einem Autobauer oder Zulieferer zu arbeiten? Welche Berufe sind am meisten gefragt?"}, {"key": "C", "text": "Firmen setzen auf flexible Arbeitsbedingungen: In vielen Branchen sind Fachkräfte gefragt wie nie zuvor. Dabei haben immer mehr Firmen Schwierigkeiten, ihre Angestellten langfristig zu halten. Wer kann, wechselt schnell zu einem Arbeitgeber mit besseren Bedingungen. Viele große Unternehmen setzen nun verstärkt auf Flexibilität und familienfreundliche Leistungen wie Firmen-Kita oder Homeoffice."}, {"key": "D", "text": "Förderung von Selbstständigen: In den letzten Jahren ist die Zahl der Selbstständigen stetig gestiegen. Das liegt unter anderem auch an neuen staatlichen Förderungsmöglichkeiten für Jungunternehmer, die ihren eigenen Betrieb aufmachen möchten."}, {"key": "E", "text": "Sein eigener Chef sein! Du willst keine starren Arbeitszeiten, weiten Anfahrtswege und keinen nervigen Umgang mit Kollegen und Chefs? Dann ist der Weg in die Existenzgründung eine echte Alternative. Ob als Übersetzer, Programmierer oder Steuerberater – Theo Geertz berät dich, wie du dein Fachwissen nutzen kannst, um zu Hause und auf eigene Rechnung zu arbeiten."}, {"key": "F", "text": "Ungelernte Arbeitskräfte weiterhin benachteiligt: Je höher die Qualifikation, desto besser die Chancen auf dem Arbeitsmarkt. Wer keine Berufsausbildung hat, läuft Gefahr, in die Langzeitarbeitslosigkeit abzustürzen. Wer Arbeit hat, muss als Ungelernter mit geringerem Gehalt und schlechteren Aufstiegschancen rechnen."}, {"key": "G", "text": "Möglichkeiten, mit einer Kündigung umzugehen: Du fühlst dich nach einer Kündigung gedemütigt und alleine gelassen und weißt nicht, wie es weitergehen soll? Das kann auch eine Chance sein, sich neu zu orientieren und vielleicht sogar die eigene Berufung zu finden."}, {"key": "H", "text": "Wege und Chancen: Das Bundesministerium für Bildung und Forschung unterstützt bei der beruflichen Qualifizierung. Es hat ein Portal eingerichtet, um vor allem Ungelernte und Geringqualifizierte sowie Arbeitnehmer in Elternzeit über passende Aus- und Weiterbildungsmöglichkeiten zu informieren."}], "bankTitle": "Informationen", "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 0),
    ('lv2', 'Lesen', 'Lesen, Teil 2', 12, 'Lesen Sie den Text und die Aufgaben 6–9. Entscheiden Sie, welche Lösung richtig ist.', 'mc', '{"passages": [{"paragraphs": [{"t": "Willkommensmappe für neue Mitarbeiterinnen und Mitarbeiter", "b": true}, {"t": "Text 1: Arbeitszeit", "b": true}, {"t": "In unserem Unternehmen arbeiten wir nach dem Gleitzeitsystem. Die Kernarbeitszeit ist Montag bis Freitag zwischen 9.00 Uhr und 15.30 Uhr. In dieser Zeit müssen alle Mitarbeitenden anwesend sein. Jede Abwesenheit während dieser Zeit muss genehmigt sein.", "b": false}, {"t": "Die tägliche Rahmenarbeitszeit ist von 6.00 Uhr bis 19.30 Uhr. Bitte beachten Sie, dass innerhalb dieses Zeitrahmens maximal acht, in Ausnahmefällen zehn, Stunden täglich gearbeitet werden darf.", "b": false}, {"t": "Alle Mitarbeitenden müssen beim Betreten und Verlassen des Gebäudes mit der Zeiterfassungskarte am Lesegerät ein- und ausstechen. So wird die tägliche Arbeitszeit auf dem Zeitkonto festgehalten. Dieses kann jederzeit am Lesegerät eingesehen werden.", "b": false}, {"t": "Bei entsprechendem Guthaben kann einmal pro Monat ein ganzer Arbeitstag (acht Stunden) als Gleitzeittag genommen werden. Zu berücksichtigen ist, dass ein Minuskontostand im Folgemonat auszugleichen ist. Zusätzlich können im Monat Dezember bis zu vier Arbeitstage als Gleitzeittage genommen werden, um sie zwischen Weihnachten und Neujahr zu nutzen, wenn das Arbeitszeitkonto ein ausreichendes Guthaben aufweist.", "b": false}, {"t": "Text 2: Wichtige Hinweise zum Datenschutz", "b": true}, {"t": "Unser Unternehmen ist dem Datenschutz gemäß der EU-Datenschutz-Grundverordnung (DSGVO) verpflichtet. Grundsätzlich dürfen die Daten unserer Mitarbeiterinnen und Mitarbeiter nur dann erhoben werden, wenn diese vorher ausdrücklich zugestimmt haben. Mit Ihrem Arbeitsvertrag haben Sie bereits ein Formular erhalten, mit dessen Unterschrift Sie bestätigt haben, dass Sie mit der Speicherung Ihrer personenbezogenen Daten einverstanden sind. Sollten Sie zukünftig Fragen zum Datenschutz haben, können Sie sich an unseren internen Datenschutzbeauftragten Herrn Koljak (Durchwahl -814) oder seine Stellvertreterin Frau Dombrovski (Durchwahl -485) wenden.", "b": false}, {"t": "Wir erwarten von unseren Mitarbeiterinnen und Mitarbeitern, sich beim Thema Datenschutzverordnung immer auf dem neuesten Stand zu halten und bieten daher jedes Jahr Schulungen zu diesem Zweck an. Diese werden von unserem externen Schulungspartner WissMax durchgeführt und finden zu unterschiedlichen Terminen, jeweils am Wochenende, bei uns im Haus statt. Der Besuch des Seminars wird als Arbeitszeit angerechnet und ist für unsere Mitarbeiter kostenfrei. Eine Teilnahme an einem solchen Training muss spätestens alle drei Jahre erfolgen und durch ein Zertifikat nachgewiesen werden. Reichen Sie dieses bitte unaufgefordert bei der Personalabteilung ein.", "b": false}]}], "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 1),
    ('lv3', 'Lesen', 'Lesen, Teil 3', 10, 'Lesen Sie die Situationen 10–13 und die Forumsbeiträge a–f. Welcher Beitrag passt zu welcher Situation? Wenn kein Beitrag passt, wählen Sie X.', 'matching', '{"bank": [{"key": "A", "text": "Susi: Solange du nicht weniger arbeitest als im Vertrag vereinbart, müsstest du rechtlich auf der sicheren Seite sein. Wenn du es genau wissen willst, solltest du in diesem Fall einen Anwalt für Arbeitsrecht kontaktieren. Mit einer Rechtsschutzversicherung wird das auch nicht so teuer."}, {"key": "B", "text": "Julia: Rein rechtlich kannst du das nicht ohne Zustimmung deiner Eltern machen. Sie müssen die Kündigung sogar unterschreiben. An deiner Stelle würde ich mir das aber noch mal überlegen. Ich kann deinen Vater jedenfalls gut verstehen. Er macht sich halt Sorgen um deine Zukunft."}, {"key": "C", "text": "Jürgen: Hi, ich würde die Ausbildung auf keinen Fall abbrechen. Mit Berufen im Finanzbereich hast du gute Aussichten auf dem Arbeitsmarkt und verdienst später auch gutes Geld. Mach dir das nicht kaputt. Meine Tochter ist Steuerberaterin und sucht händeringend nach fähigen Mitarbeitern. Sie kann sich vor Aufträgen gar nicht retten."}, {"key": "D", "text": "Jochen: Also ich würde noch warten, bis dein Kind etwas größer ist, und mich jetzt noch nicht um einen Ausbildungsplatz bewerben. Wenn es etwas selbstständiger ist, wird vieles leichter. Eine Ausbildung kannst du auch in drei oder vier Jahren noch machen. Dein Kind braucht dich jetzt."}, {"key": "E", "text": "Achim: Schutz von Leben und Gesundheit ist das oberste Gebot. Um dich und dein Kind zu schützen, darfst du während der Schwangerschaft keine körperlich anstrengenden Arbeiten verrichten und auch Tätigkeiten, bei denen du Lärm, Schmutz, Kälte usw. ausgesetzt bist, sind tabu."}, {"key": "F", "text": "Peter: Warum das denn? Es gibt doch heutzutage Möglichkeiten, das Kind unterzubringen, während man arbeitet. Können dich deine Eltern vielleicht unterstützen? Sprich mal mit deinem Chef! Wenn der sieht, dass dir die Ausbildung wichtig ist, wird sich eine Lösung finden. Aber versuch auf jeden Fall, die Ausbildung durchzuziehen."}, {"key": "X", "text": "Kein Beitrag passt."}], "bankTitle": "Forumsbeiträge", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 2),
    ('lv4', 'Lesen', 'Lesen, Teil 4', 13, 'Lesen Sie das Protokoll und die Aufgaben 14–18. Welche Lösung (A, B oder C) ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Protokoll 14.02.20XX, 08:00–11:45 Uhr", "b": true}, {"t": "Abteilung 4, Besprechungszimmer 2", "b": false}, {"t": "Teilnehmende: Holger Marschke (HM, Teamleiter), Cornelia Markert (CM, Marketingabteilung), Susanne Willke (SW, Marketingabteilung), Monique Rüdiger (MR, Betriebsratsmitglied)", "b": false}, {"t": "Entschuldigt: Martin Hamann (MH, Qualitätssicherung)", "b": false}, {"t": "Protokollantin: Marianne Schiller (MS)", "b": false}, {"t": "Sitzungsleitung: Andreas Mertens (AM)", "b": false}, {"t": "Tagesordnungspunkte:", "b": false}, {"t": "1. Begrüßung und Genehmigung des letzten Protokolls", "b": false}, {"t": "2. Neue Marketingmaßnahmen", "b": false}, {"t": "3. Qualitätsmanagement", "b": false}, {"t": "4. Anpassung der Pausenzeiten", "b": false}, {"t": "5. Standorte der neuen Fahrradständer", "b": false}, {"t": "6. Sonstiges", "b": false}, {"t": "TOP 1 Begrüßung und Genehmigung des letzten Protokolls: AM begrüßt alle Teilnehmenden und eröffnet die heutige Sitzung. Das Protokoll des letzten Meetings am 10.01.20XX wird ohne weitere Änderungen und Ergänzungen einstimmig per Handzeichen genehmigt. Auf Antrag von MR, die wegen anderweitiger terminlicher Verpflichtungen nicht bis zum Ende am Meeting teilnehmen kann, wird die Reihenfolge der Tagesordnung geändert und die TOPs 4 und 5 werden am heutigen Vormittag vorgezogen.", "b": false}, {"t": "TOP 2 Neue Marketingmaßnahmen: CM und SW berichten, dass traditionelle Marketingmaßnahmen wie z. B. Fernsehwerbung zu den Hauptsendezeiten zu teuer sind. Deshalb sollen soziale Medien wie Facebook, Instagram u. a. verstärkt genutzt werden. Weitere Möglichkeiten, Werbung zu machen, müssen von der Marketingabteilung noch erörtert werden. Es ist geplant, neue Wege zu gehen und zusätzlich zu den lokalen Geschäften einen Online-Shop zu starten. Für alle diese Maßnahmen steht insgesamt ein Budget von 150.000 € zur Verfügung. CM wird beauftragt, dafür eine spezialisierte Werbeagentur zu finden sowie einen Kostenvoranschlag der betreffenden Agentur einzuholen. SW soll Kontakte zu professionellen Fotografen und Textern herstellen und Angebote anfordern. Ergebnisse der beiden Recherchen werden bei der nächsten Besprechung am 10.03.20XX vorgestellt. Das weitere Vorgehen wird definiert, wenn alle nötigen Informationen vorliegen.", "b": false}, {"t": "TOP 3 Qualitätsmanagement: Zu den in der Besprechung vom 11.01.20XX vorgeschlagenen Maßnahmen hat MH im Vorfeld allen Sitzungsteilnehmenden erste Ergebnisse des Arbeitskreises „Optimierung innerer Kommunikationsstrukturen\" in Form eines Konzeptpapiers zukommen lassen. Da MH an der heutigen Sitzung aus gesundheitlichen Gründen nicht teilnehmen kann, ist gemeinsam beschlossen worden, die Diskussion zu diesem Punkt bis zur nächsten Besprechung am 10.03.20XX zu vertagen. Damit ist die Umsetzung der geplanten Veränderungen auf das nächste Quartal verschoben.", "b": false}, {"t": "TOP 4 Anpassung der Pausenzeiten: Aufgrund mehrfacher Anfragen von Seiten der Abteilungsleiter regt MR an, dass die Zeiten, in denen Pausen gemacht werden können, flexibler gestaltet werden. Sie schlägt ein erweitertes Zeitfenster zwischen 11:30 Uhr und 13:00 Uhr vor, in dem eine Mittagspause von 30 Minuten gemacht werden kann. So können die betrieblichen Notwendigkeiten und Arbeitsabläufe verschiedener Abteilungen besser berücksichtigt werden. Dieser Vorschlag wird einstimmig angenommen. MR wird beauftragt, eine entsprechende Mitteilung an die Belegschaft über die Änderung der Pausenzeiten zu verfassen.", "b": false}, {"t": "TOP 5 Standorte der neuen Fahrradständer: MR teilt mit, dass auf Wunsch der Belegschaft zwei weitere Fahrradständer auf dem Gelände aufgestellt werden. Dabei wurden zwei Standorte favorisiert und der erste Fahrradständer wird neben Tor 2, der zweite neben Tor 3 installiert. So steht den Mitarbeitenden nun an jedem Zugang zum Gelände eine Möglichkeit zur Verfügung, ihr Fahrrad abzustellen. Dementsprechend werden der Lageplan überarbeitet und die neuen Standorte der Fahrradständer eingezeichnet. MR formuliert dazu eine Mitteilung und wird diese intern kommunizieren und am Schwarzen Brett des Betriebsrats aushängen.", "b": false}, {"t": "TOP 6 Sonstiges: Die Assistentin der Geschäftsleitung, Frau Schlosser, verabschiedet sich in den Mutterschutz und die anschließende Elternzeit. Ansprechpartnerin bis zu ihrer Rückkehr wird für alle ab sofort Frau Meier im Büro von Frau Schmidt sein. Frau Meier wird eine Abschiedsfeier für den 16.03.20XX organisieren und sich auch um kleine Geschenke für Mutter und Kind im Namen der Kolleginnen und Kollegen kümmern.", "b": false}]}], "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 3),
    ('lvs1', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 1', 5, 'Lesen Sie die E-Mail und die Aufgaben 19–20. Welche Lösung ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Beschwerde über ausstehende Lieferung (Tischlampen)", "b": true}, {"t": "Sehr geehrter Herr Richter,", "b": false}, {"t": "vergangene Woche habe ich bei Ihnen 25 Tischlampen Modell TS 13 150 07 für unsere neuen Büroräume bestellt. Mir wurde telefonisch zugesagt, dass die Lampen noch diese Woche geliefert werden, aber jetzt ist schon Freitagnachmittag und sie sind leider noch immer nicht eingetroffen.", "b": false}, {"t": "Das ist ärgerlich, da wir am Wochenende unsere Renovierungsarbeiten beenden und die Büros dann vollständig neu einrichten werden. Dazu würden natürlich auch die Lampen gehören, da wir am Montag unseren Bürobetrieb in funktionstüchtigen Räumen wieder aufnehmen wollen.", "b": false}, {"t": "Ich habe bereits mehrfach versucht, Sie telefonisch zu erreichen, und habe Nachrichten auf Ihrem Anrufbeantworter hinterlassen, aber ich wurde leider nicht zurückgerufen. Inzwischen habe ich einen Lieferanten gefunden, der uns kurzfristig andere Tischlampen liefern könnte. Wenn Ihre Lampen also bis Montagmittag, 13:00 Uhr, nicht bei uns eingetroffen sind, werde ich die Bestellung bei Ihnen stornieren. Ich bitte um eine schnelle Antwort!", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Evelyn Berger", "b": false}]}], "maxPoints": 6, "availablePoints": 6, "missing": 0, "pointsPerItem": 3}'::jsonb, 4),
    ('lvs2', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 2', 15, 'Antworten Sie auf die Beschwerde.', 'writing', '{"passages": [{"paragraphs": [{"t": "Arbeitsanweisung von Ihrem Vorgesetzten:", "b": true}, {"t": "Lieber Herr Klein,", "b": false}, {"t": "ich habe schon wieder eine Beschwerde einer Kundin vorliegen. Sie hat ihre bestellten Tischlampen nicht bekommen. Bitte antworten Sie Frau Berger und erklären Sie ihr, warum wir im Moment Lieferschwierigkeiten haben. Versuchen Sie auch, sie davon zu überzeugen, noch bis nächste Woche zu warten und den Auftrag nicht zu stornieren. Bieten Sie ihr außerdem ein ähnliches Modell an, das wir auf Lager haben. Danke!", "b": false}, {"t": "Herzliche Grüße", "b": false}, {"t": "Knut Richter", "b": false}]}], "maxPoints": 7, "availablePoints": 7, "missing": 0, "pointsPerItem": 7}'::jsonb, 5),
    ('hv1', 'Hören', 'Hören, Teil 1', 6, 'Sie hören drei Gespräche. Zu jedem Gespräch gibt es zwei Aufgaben. Entscheiden Sie, ob die Aussage richtig oder falsch ist und welche Antwort am besten passt.', 'mc', '{"maxPoints": 18, "availablePoints": 18, "missing": 0, "pointsPerItem": 3}'::jsonb, 6),
    ('hv2', 'Hören', 'Hören, Teil 2', 5, 'Sie hören vier Aussagen. Welche Aussage a–f passt zu welcher Person 28–31?', 'matching', '{"bank": [{"key": "A", "text": "Die Firma möchte, dass alle Mitarbeiter ihre Englischkenntnisse verbessern."}, {"key": "B", "text": "Ein Mitarbeiter nutzt eine besondere Urlaubsregelung, um seine Sprachkenntnisse zu verbessern."}, {"key": "C", "text": "Ein Mitarbeiter hilft einem Kollegen bei einem Kundengespräch auf einer fremden Sprache."}, {"key": "D", "text": "Die Firma überlegt, ob sie weiterhin Übersetzungsdienste benötigt."}, {"key": "E", "text": "Ein Mitarbeiter plant, an einem Intensivsprachkurs im Ausland teilzunehmen."}, {"key": "F", "text": "Ein Kollege übernimmt einen Teil der Arbeit, um einem Team zu helfen."}], "bankTitle": "Aussagen", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 7),
    ('hv3', 'Hören', 'Hören, Teil 3', 5, 'Sie hören einen Vortrag. Wählen Sie für die Aufgaben 32–35 die richtige Lösung A, B oder C.', 'mc', '{"maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 8),
    ('hv4', 'Hören', 'Hören, Teil 4', 4, 'Sie hören fünf Ansagen auf der Mailbox. Wählen Sie für die Aufgaben 36–40 die richtige Lösung A, B oder C.', 'mc', '{"maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 9),
    ('hvs', 'Hören und Schreiben', 'Hören und Schreiben, Telefonnotiz', 15, 'Hören Sie die Nachricht und füllen Sie die Telefonnotiz aus.', 'writing', '{"passages": [{"paragraphs": [{"t": "Telefonnotiz: Dringende Malerarbeiten", "b": true}, {"t": "Nachricht auf dem Anrufbeantworter von Dr. Mayer:", "b": false}, {"t": "„Guten Tag, hier spricht Dr. Mayer. Wir müssen dringend etwas klären. Wir hatten doch vor ein paar Tagen verabredet, dass Ihre Firma heute unsere Praxis streicht. Wir haben extra unsere Praxis geschlossen und alles für Sie vorbereitet. Und jetzt höre ich von meinen Mitarbeitern, dass die Maler gar nicht gekommen sind. Wie stellen Sie sich das jetzt vor? Wir haben zuletzt vor fünf Jahren streichen lassen. Da gab es solche Probleme gar nicht. Ach ja, Sie denken auch daran, dass Sie weiße und grüne Farbe mitbringen. Ich erwarte, dass bis morgen Mittag die Wände gestrichen sind. Ich bitte dringend um Rückruf. Mein Name ist Mayer, buchstabiert M-A-Y-E-R. Sie erreichen mich unter der Nummer 05123 72 85 618. Danke und auf Wiederhören.“", "b": false}]}], "maxPoints": 9, "availablePoints": 9, "missing": 0, "pointsPerItem": 9, "audio": "telc-b2-m02-hvs.mp3", "audioPlays": 2}'::jsonb, 10),
    ('sb1', 'Sprachbausteine', 'Sprachbausteine, Teil 1', 10, 'Lesen Sie den Text und schließen Sie die Lücken 46–51. Welches Wort aus der Liste a–j passt in welche Lücke?', 'matching', '{"bank": [{"key": "A", "text": "AUFGRUND"}, {"key": "B", "text": "DA"}, {"key": "C", "text": "DABEI"}, {"key": "D", "text": "DAMIT"}, {"key": "E", "text": "DASS"}, {"key": "F", "text": "DENNOCH"}, {"key": "G", "text": "INDEM"}, {"key": "H", "text": "OB"}, {"key": "I", "text": "OBWOHL"}, {"key": "J", "text": "SOBALD"}], "bankTitle": "Wörterliste", "passages": [{"paragraphs": [{"t": "Rückfragen zum Arbeitsvertrag", "b": true}, {"t": "Sehr geehrter Herr Salzmann,", "b": false}, {"t": "meinen Arbeitsvertrag habe ich heute mit der Post erhalten und möchte mich hiermit herzlich bedanken. Ich habe ihn ausführlich geprüft und (46) haben sich noch einige Fragen ergeben.", "b": false}, {"t": "Bei meinem Vorstellungsgespräch hatte Frau Ott mir mündlich ein Jobticket zugesagt, das im Vertrag nicht erwähnt wird. Kann ich (47) fest mit dieser Zusatzleistung rechnen?", "b": false}, {"t": "Meine zweite Frage bezieht sich auf den Arbeitsort. Im Vertrag steht, (48) Mitarbeiter bei Bedarf auch an einem anderen Ort in Deutschland eingesetzt werden können. Gilt das auch für meine Stelle? Das war mir nicht bewusst und wäre (49) meiner familiären Situation momentan schwierig. (50) ich, wie Sie wissen, zwei schulpflichtige Kinder habe, wäre ein Umzug für meine Familie nicht möglich.", "b": false}, {"t": "Ich freue mich auf Ihre Rückmeldung und schicke Ihnen den Vertrag unverzüglich unterschrieben zurück, (51) diese Punkte geklärt sind.", "b": false}, {"t": "Ich freue mich auf meinen Arbeitsbeginn am 1. Juli.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Irina Lopez", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 11),
    ('sb2', 'Sprachbausteine', 'Sprachbausteine, Teil 2', 10, 'Lesen Sie den Text und schließen Sie die Lücken 52–57. Welche Lösung (A, B oder C) ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Ihre Beschwerde bezüglich des beschädigten Produktes", "b": true}, {"t": "Sehr geehrte Frau Janiashvilli,", "b": false}, {"t": "wir danken Ihnen für Ihr Schreiben, mit dem Sie uns auf die Schäden an der Bettcouch aufmerksam machen, die Sie bei uns gekauft haben.", "b": false}, {"t": "Wir haben (52) und teilen Ihre Ansicht.", "b": false}, {"t": "Offensichtlich ist bei unserer Qualitätskontrolle (53) worden.", "b": false}, {"t": "(54) hätte die Couch nicht ausgeliefert werden dürfen.", "b": false}, {"t": "Heute erhalten Sie das Ersatzprodukt, das beschädigte Möbelstück wird dann kostenlos mitgenommen.", "b": false}, {"t": "Wir bitten Sie, die entstandenen (55), und wünschen Ihnen viel Vergnügen mit Ihrem neuen Sitzmöbel. Ihre Reklamation haben wir an die Abteilung für Qualitätssicherung weitergegeben, um sicherzustellen, dass solche Fehler zukünftig vermieden werden.", "b": false}, {"t": "Als kleines Dankeschön für Ihr Verständnis finden Sie anbei einen Gutschein (56) 50 Euro für Ihren nächsten Besuch in unserem Haus.", "b": false}, {"t": "Wir würden uns freuen, Sie bald wieder in einer unserer Filialen (57).", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Ludmilla Dombrowski", "b": false}, {"t": "Leiterin Kundenservice", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 12)
) as v(section_id, grp, title, minutes, instruction, format, config, sort)
join tests t on t.level_id = 'telc-b2' and t.slug = 'modell-02'
on conflict (test_id, section_id) do update set "group" = excluded."group", title = excluded.title, minutes = excluded.minutes, instruction = excluded.instruction, format = excluded.format, config = excluded.config, sort = excluded.sort;

insert into items (section_id, item_id, text, options, points, meta, sort)
select s.id, v.item_id, v.text, v.options, v.points, v.meta, v.sort
from (values
    ('lv1', '1', 'Junis ist gelernter Kfz-Mechatroniker und möchte eine eigene Werkstatt gründen.', null::jsonb, 3, null::jsonb, 0),
    ('lv1', '2', 'Maria arbeitet als Hilfsarbeiterin und möchte nun eine Berufsausbildung machen.', null::jsonb, 3, null::jsonb, 1),
    ('lv1', '3', 'Nikolett möchte sich nicht zwischen Familie und Arbeit entscheiden müssen.', null::jsonb, 3, null::jsonb, 2),
    ('lv1', '4', 'Amin studiert Fremdsprachen und möchte nach seinem Abschluss freiberuflich arbeiten.', null::jsonb, 3, null::jsonb, 3),
    ('lv1', '5', 'Samita soll aus betriebsbedingten Gründen gekündigt werden und sie möchte dagegen vorgehen.', null::jsonb, 3, null::jsonb, 4),
    ('lv2', '6', 'Bei Gleitzeit können Mitarbeitende täglich beliebig viele Stunden arbeiten.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('lv2', '7', 'Durch Gleitzeit ist es den Mitarbeitenden möglich,', '[{"key": "A", "text": "ein Stundenguthaben aufzubauen."}, {"key": "B", "text": "jeden Monat einige Tage freizunehmen."}, {"key": "C", "text": "täglich mehr als acht Stunden zu arbeiten."}]'::jsonb, 3, null::jsonb, 1),
    ('lv2', '8', 'Die Mitarbeiter müssen einmal pro Jahr ein Seminar zum Datenschutz belegen.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 2),
    ('lv2', '9', 'Die Teilnahme am Seminar', '[{"key": "A", "text": "gilt als Arbeitszeit."}, {"key": "B", "text": "ist kostenpflichtig."}, {"key": "C", "text": "muss bei WissMax im externen Schulungszentrum erfolgen."}]'::jsonb, 3, null::jsonb, 3),
    ('lv3', '10', 'Inka: Ich bin Auszubildende in einem Büro und muss immer pünktlich Feierabend machen, weil ich meinen einjährigen Sohn von der Krippe abholen muss. Mein Chef sieht das gar nicht gern und droht mir jetzt sogar mit Kündigung. Was soll ich machen?', null::jsonb, 3, null::jsonb, 0),
    ('lv3', '11', 'Jacqueline: Hallo Leute! Vor ein paar Monaten habe ich mit einer Ausbildung begonnen. Und jetzt bin ich schwanger... Was soll ich bloß machen? Es wird bestimmt schwierig, Kind und Arbeit zu vereinbaren. Soll ich die Ausbildung abbrechen?', null::jsonb, 3, null::jsonb, 1),
    ('lv3', '12', 'Hans-Peter: Guten Abend, ich bin Ende 40 und mein Sohn ist inzwischen erwachsen. Jetzt möchte ich beruflich was ganz Neues machen und eine Ausbildung zum Steuerfachangestellten anfangen. Meint ihr, ich habe in meinem Alter noch Chancen, in diesem Beruf zu arbeiten?', null::jsonb, 3, null::jsonb, 2),
    ('lv3', '13', 'Max: Hallo, ich mache momentan eine Ausbildung zum Einzelhandelskaufmann. Ich habe noch ein Jahr bis zum Abschluss und habe wirklich keine Lust mehr. Mein Vater möchte, dass ich die Ausbildung fertig mache. Ich bin noch nicht 18. Kann ich trotzdem einfach kündigen?', null::jsonb, 3, null::jsonb, 3),
    ('lv4', '14', 'Für neue Werbemaßnahmen', '[{"key": "A", "text": "werden kreative Mitarbeiter gesucht."}, {"key": "B", "text": "wird ein Gesamtbetrag von 150.000 € bereitgestellt."}, {"key": "C", "text": "wurden bereits Kostenvoranschläge eingeholt."}]'::jsonb, 3, null::jsonb, 0),
    ('lv4', '15', 'Herr Hamann', '[{"key": "A", "text": "hat bereits ein Konzept vorbereitet."}, {"key": "B", "text": "ist dienstlich verhindert."}, {"key": "C", "text": "stellt die Resultate seiner Arbeit vor."}]'::jsonb, 3, null::jsonb, 1),
    ('lv4', '16', 'Die Mittagspause', '[{"key": "A", "text": "ist 30 Minuten lang."}, {"key": "B", "text": "wird um 30 Minuten verlängert."}, {"key": "C", "text": "wird um 30 Minuten verschoben."}]'::jsonb, 3, null::jsonb, 2),
    ('lv4', '17', 'Der Standort der neuen Fahrradständer', '[{"key": "A", "text": "wird an der Informationstafel bekanntgegeben."}, {"key": "B", "text": "wird dem Betriebsrat mitgeteilt."}, {"key": "C", "text": "wird zwischen Tor 2 und 3 geplant."}]'::jsonb, 3, null::jsonb, 3),
    ('lv4', '18', 'Frau Schlosser', '[{"key": "A", "text": "macht Frau Schmidt ein Geschenk."}, {"key": "B", "text": "verlässt das Unternehmen für immer."}, {"key": "C", "text": "wird von Frau Meier vertreten."}]'::jsonb, 3, null::jsonb, 4),
    ('lvs1', '19', 'Frau Berger', '[{"key": "A", "text": "beschwert sich über die Qualität des Produktes."}, {"key": "B", "text": "hat eine fehlerhafte Lieferung erhalten."}, {"key": "C", "text": "wartet dringend auf die Lieferung."}]'::jsonb, 3, null::jsonb, 0),
    ('lvs1', '20', 'Die Renovierungsarbeiten', '[{"key": "A", "text": "stehen kurz bevor."}, {"key": "B", "text": "verzögern sich unbestimmt."}, {"key": "C", "text": "sollen zeitnah abgeschlossen werden."}]'::jsonb, 3, null::jsonb, 1),
    ('lvs2', 'B', 'Antworten Sie Frau Berger auf ihre Beschwerde im Namen von Lukas Klein.', null::jsonb, 0, '{"points": ["Bedauern über die Verzögerung und Entschuldigung für die Unannehmlichkeiten", "Erklärung der unvorhergesehenen Lieferschwierigkeiten beim Hersteller", "Bitte um Geduld bis zur kommenden Woche", "Angebot eines alternativen, sofort lieferbaren Modells vom Lager"]}'::jsonb, 0),
    ('hv1', '22', 'Die Kundin braucht eine Beratung für neue Bürogeräte.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('hv1', '23', 'Die Kundin möchte', '[{"key": "A", "text": "mindestens fünf Drucker kaufen."}, {"key": "B", "text": "mit ihrem Vorgesetzten reden."}, {"key": "C", "text": "sofort ein Großraumgerät bestellen."}]'::jsonb, 3, null::jsonb, 1),
    ('hv1', '24', 'Die Organisation des Betriebsfestes ist bereits abgeschlossen.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 2),
    ('hv1', '25', 'Für die Betriebsfeier', '[{"key": "A", "text": "wird eine neue Cateringfirma gesucht."}, {"key": "B", "text": "soll eine neue Band gesucht werden."}, {"key": "C", "text": "wurde der genaue Termin noch nicht endgültig festgelegt."}]'::jsonb, 3, null::jsonb, 3),
    ('hv1', '26', 'Frau Schmidt und Herr Klein arbeiten beide im Lager.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 4),
    ('hv1', '27', 'Frau Schmidt', '[{"key": "A", "text": "gibt Herrn Klein direkt die Schutzkleidung."}, {"key": "B", "text": "stellt Herrn Klein seinem Vorgesetzten vor."}, {"key": "C", "text": "verlangt noch weitere Unterlagen von Herrn Klein."}]'::jsonb, 3, null::jsonb, 5),
    ('hv2', '28', 'Person 1', null::jsonb, 3, null::jsonb, 0),
    ('hv2', '29', 'Person 2', null::jsonb, 3, null::jsonb, 1),
    ('hv2', '30', 'Person 3', null::jsonb, 3, null::jsonb, 2),
    ('hv2', '31', 'Person 4', null::jsonb, 3, null::jsonb, 3),
    ('hv3', '32', 'Das Unternehmen', '[{"key": "A", "text": "hat für den Arbeitsschutz ein externes Fachunternehmen beauftragt."}, {"key": "B", "text": "wird alle Mitarbeiter einzeln persönlich befragen."}, {"key": "C", "text": "wird intern einen neuen Fragebogen entwickeln."}]'::jsonb, 3, null::jsonb, 0),
    ('hv3', '33', 'Die ausgefüllten Fragebögen werden', '[{"key": "A", "text": "intern im Betrieb ausgewertet."}, {"key": "B", "text": "nach der Analyse dauerhaft archiviert."}, {"key": "C", "text": "von externen Fachleuten analysiert und danach vernichtet."}]'::jsonb, 3, null::jsonb, 1),
    ('hv3', '34', 'Die Mitarbeiter müssen', '[{"key": "A", "text": "alle Fluchtwege wöchentlich kontrollieren."}, {"key": "B", "text": "bei Feueralarm sämtliche Arbeitsunterlagen mitnehmen."}, {"key": "C", "text": "im Brandfall ihren vorgesehenen Sammelpunkt kennen."}]'::jsonb, 3, null::jsonb, 2),
    ('hv3', '35', 'Die Geschäftsführung', '[{"key": "A", "text": "bietet einen Erste-Hilfe-Kurs für ausnahmslos alle Angestellten an."}, {"key": "B", "text": "sucht zwei weitere Mitarbeitende, die sich als Ersthelfer ausbilden lassen."}, {"key": "C", "text": "verabschiedet heute Herrn Fischer in den Ruhestand."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '36', 'Robert Krüger', '[{"key": "A", "text": "hat im letzten Jahr die Weihnachtsfeier organisiert."}, {"key": "B", "text": "möchte unbedingt wieder beim Griechen feiern."}, {"key": "C", "text": "denkt bei der Restaurantwahl an die Interessen von Vegetariern."}]'::jsonb, 3, null::jsonb, 0),
    ('hv4', '37', 'Katrin', '[{"key": "A", "text": "will Bettina mit einem persönlichen Geschenk überraschen."}, {"key": "B", "text": "sucht eine Anregung für ein Gemeinschaftsgeschenk."}, {"key": "C", "text": "möchte ein Geschenk für maximal fünf Euro kaufen."}]'::jsonb, 3, null::jsonb, 1),
    ('hv4', '38', 'Stefan Körner bittet seinen Kollegen,', '[{"key": "A", "text": "die Wartung der Brandmelder sofort selbst durchzuführen."}, {"key": "B", "text": "einen Termin mit der Brandschutzfirma zu vereinbaren."}, {"key": "C", "text": "neue Brandmelder im Internet zu bestellen."}]'::jsonb, 3, null::jsonb, 2),
    ('hv4', '39', 'Barbara', '[{"key": "A", "text": "organisiert ganz allein das Begegnungsfest."}, {"key": "B", "text": "wird den französischen Gästen die Firma zeigen."}, {"key": "C", "text": "kümmert sich um die Verpflegung der Gäste."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '40', 'Michaell Brüger möchte, dass', '[{"key": "A", "text": "die ausgefallene Heizung schnellstmöglich repariert wird."}, {"key": "B", "text": "er erst in den nächsten Tagen zurückgerufen wird."}, {"key": "C", "text": "alle Heizkörper im Gebäude ausgetauscht werden."}]'::jsonb, 3, null::jsonb, 4),
    ('hvs', '41', 'Dokumentieren Sie die telefonische Beschwerde:', null::jsonb, 0, '{"points": ["Anrufer (Dr. Mayer, M-A-Y-E-R)", "Telefonnummer für Rückruf (05123 72 85 618)", "Grund des Anrufs (Maler nicht erschienen trotz geschlossener Praxis)", "Wichtige Details (Wände müssen bis morgen Mittag mit weißer und grüner Farbe gestrichen sein)", "Zu erledigen (Dringender Rückruf)"]}'::jsonb, 0),
    ('sb1', '46', '… ausführlich geprüft und (46) haben sich noch einige Fragen ergeben. …', null::jsonb, 0.5, null::jsonb, 0),
    ('sb1', '47', '… im Vertrag nicht erwähnt wird. Kann ich (47) fest mit dieser Zusatzleistung rechnen? …', null::jsonb, 0.5, null::jsonb, 1),
    ('sb1', '48', '… Im Vertrag steht, (48) Mitarbeiter bei Bedarf auch an einem anderen Ort …', null::jsonb, 0.5, null::jsonb, 2),
    ('sb1', '49', '… Das war mir nicht bewusst und wäre (49) meiner familiären Situation momentan schwierig. …', null::jsonb, 0.5, null::jsonb, 3),
    ('sb1', '50', '… momentan schwierig. (50) ich, wie Sie wissen, zwei schulpflichtige Kinder habe, …', null::jsonb, 0.5, null::jsonb, 4),
    ('sb1', '51', '… schicke Ihnen den Vertrag unverzüglich unterschrieben zurück, (51) diese Punkte geklärt sind. …', null::jsonb, 0.5, null::jsonb, 5),
    ('sb2', '52', '… Bettcouch aufmerksam machen, die Sie bei uns gekauft haben. Wir haben (52) und teilen Ihre Ansicht. …', '[{"key": "A", "text": "Ihren Auftrag angenommen"}, {"key": "B", "text": "Ihre Bestellung erhalten"}, {"key": "C", "text": "Ihre Reklamation geprüft"}]'::jsonb, 0.5, null::jsonb, 0),
    ('sb2', '53', '… Offensichtlich ist bei unserer Qualitätskontrolle (53) worden. …', '[{"key": "A", "text": "das Problem unbemerkt"}, {"key": "B", "text": "der Mangel übersehen"}, {"key": "C", "text": "der Schaden behoben"}]'::jsonb, 0.5, null::jsonb, 1),
    ('sb2', '54', '… der Mangel übersehen worden. (54) hätte die Couch nicht ausgeliefert werden dürfen. …', '[{"key": "A", "text": "Auf dieser Stelle"}, {"key": "B", "text": "In diesem Zustand"}, {"key": "C", "text": "Mit dieser Position"}]'::jsonb, 0.5, null::jsonb, 2),
    ('sb2', '55', '… Wir bitten Sie, die entstandenen (55), und wünschen Ihnen viel Vergnügen mit Ihrem neuen Sitzmöbel. …', '[{"key": "A", "text": "Fehler zu beanstanden"}, {"key": "B", "text": "Probleme zu berücksichtigen"}, {"key": "C", "text": "Unannehmlichkeiten zu entschuldigen"}]'::jsonb, 0.5, null::jsonb, 3),
    ('sb2', '56', '… Als kleines Dankeschön für Ihr Verständnis finden Sie anbei einen Gutschein (56) 50 Euro für Ihren nächsten Besuch …', '[{"key": "A", "text": "für den Betrag von"}, {"key": "B", "text": "in Höhe von"}, {"key": "C", "text": "zum Preis von"}]'::jsonb, 0.5, null::jsonb, 4),
    ('sb2', '57', '… Wir würden uns freuen, Sie bald wieder in einer unserer Filialen (57). Mit freundlichen Grüßen …', '[{"key": "A", "text": "begrüßen zu dürfen"}, {"key": "B", "text": "beobachten zu dürfen"}, {"key": "C", "text": "besuchen zu dürfen"}]'::jsonb, 0.5, null::jsonb, 5)
) as v(section_id, item_id, text, options, points, meta, sort)
join tests t on t.level_id = 'telc-b2' and t.slug = 'modell-02'
join sections s on s.test_id = t.id and s.section_id = v.section_id
on conflict (section_id, item_id) do update set text = excluded.text, options = excluded.options, points = excluded.points, meta = excluded.meta, sort = excluded.sort;

