insert into sections (test_id, section_id, "group", title, minutes, instruction, format, config, sort)
select t.id, v.section_id, v.grp, v.title, v.minutes, v.instruction, v.format, v.config, v.sort
from (values
    ('lv1', 'Lesen', 'Lesen, Teil 1', 10, 'Lesen Sie die Aufgaben 1–5 und die Informationen a–h. Welche Information passt zu welcher Situation?', 'matching', '{"bank": [{"key": "A", "text": "Pflegefreistellung für Mütter und Väter: Arbeitnehmerinnen und Arbeitnehmer haben das Recht auf Freistellung am Arbeitsplatz, wenn ein im Haushalt lebendes Kind erkrankt und keine Betreuungsmöglichkeit vorhanden ist. Die Freistellung ist pro Arbeitsjahr begrenzt. In der Probezeit sollte man damit vorsichtig sein, da hier andere Kündigungsfristen gelten."}, {"key": "B", "text": "Tipps für Frauen im Beruf: Frauen verkaufen sich oft unter Wert. Es ist besonders wichtig, dass Sie ausreichend über Ihre Rechte im Berufsleben informiert sind. Unsere Expertin für Arbeitsrecht gibt Tipps für Gehaltsverhandlungen und ein selbstbewusstes Auftreten. Außerdem informiert sie darüber, was Sie in einem Bewerbungsgespräch nicht erzählen müssen."}, {"key": "C", "text": "Damit sich der Aufwand lohnt: Stellenangebote online zu schalten, kann für Unternehmen schnell sehr kostspielig werden. Nicht nur die Bekanntheit der Webseite ist dafür entscheidend, sondern auch die regionale Reichweite und der Grad der Spezialisierung."}, {"key": "D", "text": "Der Bundesverband der Tourismusbranche informiert: Trotz anhaltend großer Nachfrage von Seiten der Arbeitgeber ist die Zahl der Bewerbungen rückläufig. Auch auf dem Ausbildungsmarkt fehlt es an jungen Menschen, die sich für dieses Arbeitsfeld interessieren. Offene Stellen werden demzufolge zügig besetzt."}, {"key": "E", "text": "Informationen rund um den Mutterschutz: Frauen dürfen nach dem Mutterschutzgesetz während einer Schwangerschaft und bis zu vier Monate nach der Geburt nicht gekündigt werden. Voraussetzung hierfür ist jedoch, dass der Arbeitgeber zum Zeitpunkt der Kündigung von der Schwangerschaft wusste."}, {"key": "F", "text": "Rechte berufstätiger Eltern: Eltern haben keinen Rechtsanspruch darauf, ihre Kinder am Arbeitsplatz zu betreuen. Die Entscheidung unterliegt der Zustimmung des Arbeitgebers und viele sind damit einverstanden, wenn sich so vermeiden lässt, dass sich die Eltern krankschreiben lassen. Arbeitsplätze, bei denen die Sicherheit des Kindes gefährdet ist, sind von dieser Regelung ausgeschlossen."}, {"key": "G", "text": "Vom Traum zur Realität: Als angehender Gründer brauchen Sie nicht nur Branchenkenntnisse, sondern auch Wissen über betriebswirtschaftliche Vorgänge. Vom Businessplan und der richtigen Finanzierung über vernünftige Personalplanung bis hin zur Einholung der notwendigen Lizenzen kommen nun viele Dinge auf Sie zu."}, {"key": "H", "text": "Die richtige Wahl spart Zeit und Frust: Die Suche nach einer neuen Stelle ist extrem zeitaufwendig. Im Internet erscheint das Angebot an offenen Stellen riesig, dennoch bleibt der Erfolg oft aus. Eine der wichtigsten Voraussetzungen ist es also, Jobangebote richtig zu filtern, um ohne großen Zeitaufwand die richtige Anzeige zu finden."}], "bankTitle": "Informationen", "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 0),
    ('lv2', 'Lesen', 'Lesen, Teil 2', 12, 'Lesen Sie den Text und die Aufgaben 6–9. Entscheiden Sie, welche Lösung richtig ist.', 'mc', '{"passages": [{"paragraphs": [{"t": "Willkommensmappe für neue Mitarbeiterinnen und Mitarbeiter", "b": true}, {"t": "Text 1: Urlaub", "b": true}, {"t": "Jedem Mitarbeiter und jeder Mitarbeiterin in unserem Unternehmen stehen je nach Betriebszugehörigkeit bis zu 26 Tage Urlaub zu. Der Urlaub sollte nach Möglichkeit innerhalb des laufenden Kalenderjahres genommen werden. In Ausnahmefällen kann diese Frist bis zum 31.3. des Folgejahres verlängert werden.", "b": false}, {"t": "Grundsätzlich besteht der volle Urlaubsanspruch erst nach Ablauf der sechsmonatigen Probezeit. Ein anteiliger Urlaub ist jedoch nach Rücksprache auch bereits während dieser Zeit möglich.", "b": false}, {"t": "Urlaubsanträge für das folgende Kalenderjahr sind spätestens bis zum 15.11. mittels des dafür vorgesehenen Formulars beim Abteilungsleiter bzw. seiner Vertretung einzureichen. Den Urlaubswünschen der einzelnen Mitarbeiter wird entsprochen, sofern diese mit den Betriebsabläufen vereinbar sind. Sollten sich die beantragten Urlaubszeiten einzelner Kollegen und Kolleginnen überschneiden, wird nach sozialen Aspekten entschieden.", "b": false}, {"t": "Der Abteilungsleiter prüft alle Urlaubsanträge unverzüglich. Sollten die Wünsche der Mitarbeiter unvereinbar sein, wird der Betriebsrat mit dem Ziel der Einigung hinzugezogen.", "b": false}, {"t": "Text 2: Rauchen", "b": true}, {"t": "Im gesamten Betrieb gilt striktes Rauchverbot. Auf dem Betriebsgelände befinden sich vier durch Hinweisschilder gekennzeichnete Raucherzonen. Bitte benutzen Sie für Ihre Zigarettenreste die Standaschenbecher. Allerdings ist im Umkreis von mindestens 50 Metern rund um die Produktionshallen das Rauchen auch im Freien untersagt. Eine Missachtung dieser Regel zieht eine Abmahnung nach sich. Im Wiederholungsfall droht eine fristlose Kündigung.", "b": false}, {"t": "Das Rauchverbot schließt Zigaretten, Zigarren, Pfeifen und den Konsum ähnlich verwendbarer Substanzen sowie jeglichen Gebrauch von E-Zigaretten mit ein. Bei Veranstaltungen ist das Rauchen auch auf der Dachterrasse des Gebäudes A zulässig. Beschäftigte, die dort rauchen, sind dazu angehalten, die Terrassentür geschlossen zu halten.", "b": false}, {"t": "Zigarettenpausen während der Arbeitszeit sind grundsätzlich zulässig, dabei sind folgende Regelungen zu beachten: Raucherpausen sind nicht Bestandteil der Arbeitszeit, deshalb müssen sich Mitarbeiter ordnungsgemäß vom Zeiterfassungssystem ab- bzw. nach Beendigung der Pause wieder anmelden. Da die Raucherpause nicht zur Arbeitszeit gehört, greift währenddessen nach dem Arbeitsrecht die gesetzliche Unfallversicherung nicht.", "b": false}]}], "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 1),
    ('lv3', 'Lesen', 'Lesen, Teil 3', 10, 'Lesen Sie die Situationen 10–13 und die Forumsbeiträge a–f. Welcher Beitrag passt zu welcher Situation? Wenn kein Beitrag passt, wählen Sie X.', 'matching', '{"bank": [{"key": "A", "text": "Thilo: In meinen Augen ist Familie das Wichtigste auf der Welt. Es ist doch auch ein Gewinn, wenn man mehr Zeit mit seinen Kindern verbringen kann und weniger gestresst ist. Ich würde mich auf jeden Fall für Teilzeit entscheiden."}, {"key": "B", "text": "Henny: Also ich finde es nicht gut, wenn Geschäfte und Supermärkte an Samstagen so lange geöffnet sind. Ihr müsst doch bedenken, dass dort auch Menschen arbeiten müssen. Sie wollen doch ebenfalls Wochenende haben und zu ihren Familien. Ich bin ganz klar gegen längere Ladenöffnungszeiten."}, {"key": "C", "text": "Angela: Jeder Arbeitnehmer hat einen Rechtsanspruch auf Teilzeitarbeit. Allerdings musst du länger als sechs Monate bei dem Unternehmen beschäftigt sein. Man muss sich das aber genau überlegen, da man nicht nur kurz- oder mittelfristig weniger verdient, sondern auch weniger Rentenansprüche hat. Schau doch mal im Internet, wie viel das ausmacht."}, {"key": "D", "text": "Ratna: Seit Kurzem haben Arbeitnehmer das Recht, eine befristete Zeit weniger zu arbeiten, aber das gilt bestimmt nicht rückwirkend. Soviel ich weiß, hast du also keinen Anspruch, in die Vollzeit zurückzukehren. Sprich doch einfach mal mit deinem Chef."}, {"key": "E", "text": "Alex: Der Samstag ist ein normaler Werktag und deshalb kann der Arbeitgeber anordnen, dass an diesem Tag auch gearbeitet wird. Dabei spielt es keine Rolle, ob du Kinder hast oder nicht. Oft ist es aber auch so, dass du dann an einem anderen Tag in der Woche frei bekommst."}, {"key": "F", "text": "Gerhard: Also ich würde mir das gut überlegen. Wenn du bisher gut über die Runden gekommen bist, könntest du dir doch etwas mehr Freizeit gönnen. Meines Erachtens geht es hier auch um mehr Lebensqualität. Das Leben ist zu kurz, um nur zu arbeiten."}, {"key": "X", "text": "Kein Beitrag passt."}], "bankTitle": "Forumsbeiträge", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 2),
    ('lv4', 'Lesen', 'Lesen, Teil 4', 13, 'Lesen Sie das Protokoll und die Aufgaben 14–18. Welche Lösung (A, B oder C) ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Protokoll 19.11.20XX, 08:00–11:45 Uhr", "b": true}, {"t": "Zentrale, Raum 405", "b": false}, {"t": "Sitzungsleitung: Lukas Wallner (LW)", "b": false}, {"t": "Teilnehmende: Jessica Müller (JM, Personalabteilung), Maximilian Berger (MB, Marketingabteilung), Rebecca Lehmann (RL, Öffentlichkeitsarbeit), Kurt Meichsner (KM, Verkauf)", "b": false}, {"t": "Extern: Ansgar Wolf (AW, Hausverwaltung)", "b": false}, {"t": "Protokollantin: Beate Richter (BR)", "b": false}, {"t": "Tagesordnungspunkte:", "b": false}, {"t": "1. Begrüßung und Genehmigung des letzten Protokolls", "b": false}, {"t": "2. Personal", "b": false}, {"t": "3. Kundenbindung, Rabattaktion", "b": false}, {"t": "4. Vorbereitungen der Messe", "b": false}, {"t": "5. Neujahrsfeier", "b": false}, {"t": "6. Sonstiges", "b": false}, {"t": "TOP 1 Begrüßung und Genehmigung des letzten Protokolls: LW begrüßt alle Teilnehmer und eröffnet die heutige Besprechung. Herr Dr. Baumann aus der Qualitätssicherung lässt sich entschuldigen, da er in dieser Woche auf einer Dienstreise ist. Das Protokoll des Meetings vom 14. November wird ohne weitere Änderungen und Ergänzungen einstimmig per Handzeichen genehmigt.", "b": false}, {"t": "TOP 2 Personal: Die Kundenbetreuung ist aktuell unterbesetzt, weil viele Kollegen krank sind. Auch in der Personalabteilung herrscht ein hoher Krankenstand. Krankmeldungen aus allen Abteilungen sollen deshalb vorübergehend direkt an JM gesendet werden. Urlaubsanträge können im Moment nur im Falle dringender persönlicher Angelegenheiten genehmigt werden. Aufgrund des hohen Krankenstands mussten einige Kollegen in den letzten Monaten besonders viele Überstunden machen, die möglichst bis zum Ende des Kalenderjahres abgebaut werden sollten. Sollte dies aufgrund des hohen Arbeitspensums nicht möglich sein, können die Überstunden auch in das nächste Jahr übertragen werden. Herr Wortmann aus dem Verkauf geht am 1. Februar des nächsten Jahres in den Ruhestand. Sein Nachfolger wird KM, den Herr Wortmann ab sofort einarbeitet. Im Rahmen der Neujahrsfeier wird unser langjähriger Mitarbeiter verabschiedet. Wir möchten ihm zum Abschied eine Freude machen. Ideen hierzu bitte an JM, die anschließend das Geld einsammeln und das Geschenk besorgen wird. Zum 1. Dezember beginnen drei neue Mitarbeiter in der Produktion, da die Verkaufszahlen stark gestiegen sind.", "b": false}, {"t": "TOP 3 Kundenbindung, Rabattaktion: KM hat erfahren, dass der Wettbewerber Lutz GmbH für das Frühjahr eine Rabattaktion plant. RL schlägt vor, ebenfalls eine Kampagne zur Kundenbindung zu entwickeln. KM hat hierfür bereits einen ersten Entwurf für ein Konzept ausgearbeitet und legt diesen vor. Er schlägt vor, das Konzept in einer kleineren Runde zu diskutieren. Wer Interesse hat, an diesem Brainstorming teilzunehmen, soll sich bis zum Ende der Woche bei KM melden.", "b": false}, {"t": "TOP 4 Vorbereitungen der Messe: Im nächsten Jahr wird unsere Firma erstmals an der Frühjahrsmesse in Dresden teilnehmen, die vom 20.–24. April stattfindet. MB aus der Marketingabteilung berichtet, dass bereits der Standplatz gebucht und der Messebauer beauftragt ist. Interessierte können sich die Standgestaltung im Büro von MB ansehen. Auch die Broschüren zu unserem Messeauftritt sind bereits im Druck und können in der 2. KW an unsere Kunden verschickt werden. Abschließend bittet MB JM, externes Standpersonal und Hotelzimmer für die Mitarbeiter zu buchen, die auf die Messe gehen.", "b": false}, {"t": "TOP 5 Neujahrsfeier: JM berichtet, dass am 7. Januar die Neujahrsfeier im Restaurant „Zum Schwan\" stattfindet. Die Einladungen und Menüvorschläge werden verschickt. Alle Mitarbeiter sollen bis zum 15. Dezember Bescheid sagen, mit wie vielen Personen sie teilnehmen und was sie essen möchten. Die Geschäftsführung hat auch eine kleine Überraschung für die Mitarbeiter an diesem Abend geplant.", "b": false}, {"t": "TOP 6 Sonstiges: AW informiert über Renovierungsarbeiten im ersten Stock, die für die nächste Woche geplant sind. Die Firma Buntschuh wird die Wände in der Teeküche Montag und Dienstag nächster Woche streichen. Da die Küche dafür komplett ausgeräumt werden muss, werden die Mitarbeiter gebeten, bei dieser Gelegenheit persönliche Gegenstände wie zum Beispiel nicht firmeneigene Kaffeetassen, Brotdosen und Ähnliches bis Donnerstag an sich zu nehmen. Ansonsten werden diese durch AW entsorgt.", "b": false}]}], "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 3),
    ('lvs1', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 1', 5, 'Lesen Sie die E-Mail und die Aufgaben 19–20. Welche Lösung ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Entwurf für die neue Firmenwebseite", "b": true}, {"t": "Sehr geehrte Frau Spindler,", "b": false}, {"t": "vielen Dank für Ihren Entwurf für unsere neue Firmenwebseite. Ich habe ihn gemeinsam mit dem Team gesichtet und dabei ist uns aufgefallen, dass Ihre Agentur die Vorgaben an zwei Stellen leider nicht umgesetzt hat:", "b": false}, {"t": "Zum einen hatten wir besprochen, dass das Farbschema grau-orange sein sollte. Da statt Grau Blau gewählt wurde, glaube ich, dass es zu einem Missverständnis gekommen ist. Zum anderen sind auf der Seite mit den Ansprechpartnern die Namen einiger Mitarbeiter vertauscht worden. Im Anhang schicke ich Ihnen noch einmal eine Auflistung der Namen mit den dazugehörigen Bildern.", "b": false}, {"t": "Könnten Sie diese beiden Punkte bitte bis Anfang nächster Woche nachbessern? Eine kurze Rückmeldung wäre nett.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Franz Stiller", "b": false}]}], "maxPoints": 6, "availablePoints": 6, "missing": 0, "pointsPerItem": 3}'::jsonb, 4),
    ('lvs2', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 2', 15, 'Antworten Sie auf das Schreiben des Kunden.', 'writing', '{"passages": [{"paragraphs": [{"t": "Arbeitsanweisung von Ihrer Agenturchefin:", "b": true}, {"t": "Hallo Frau Holsten,", "b": false}, {"t": "ich habe heute Mittag die untenstehende Mail bekommen. Die vertauschten Namen sind unser Fehler und die verbessern wir auch. Bitte bestätigen Sie dem Kunden das. Aber mehr ist nun wirklich nicht drin. Das ist schon das fünfte Mal, dass er Korrekturwünsche hat, obwohl wir uns immer an die Vorgaben gehalten haben. So viele Korrekturen waren nicht vereinbart!", "b": false}, {"t": "Wenn wir das Farbschema noch ändern sollten, geht das nur gegen zusätzliche Bezahlung. Ich rechne mit 200 bis 300 € extra. Bitte teilen Sie ihm dies mit und lassen Sie sich von ihm sein Okay geben.", "b": false}, {"t": "Danke und viele Grüße", "b": false}, {"t": "Jutta Spindler", "b": false}]}], "maxPoints": 7, "availablePoints": 7, "missing": 0, "pointsPerItem": 7}'::jsonb, 5),
    ('hv1', 'Hören', 'Hören, Teil 1', 6, 'Sie hören drei Gespräche. Zu jedem Gespräch gibt es zwei Aufgaben. Entscheiden Sie, ob die Aussage richtig oder falsch ist und welche Antwort am besten passt.', 'mc', '{"maxPoints": 18, "availablePoints": 18, "missing": 0, "pointsPerItem": 3}'::jsonb, 6),
    ('hv2', 'Hören', 'Hören, Teil 2', 5, 'Sie hören vier Aussagen. Welche Aussage a–f passt zu welcher Person 28–31?', 'matching', '{"bank": [{"key": "A", "text": "Kleidung für die Feiertage sollte schick aussehen."}, {"key": "B", "text": "Auf der Firmenfeier gibt es keine feste Kleiderordnung."}, {"key": "C", "text": "Beim Firmenlauf sollen möglichst viele Mitarbeiter teilnehmen."}, {"key": "D", "text": "Die Firma plant aus besonderem Anlass eine Kunden-Kampagne."}, {"key": "E", "text": "Es gibt verschiedene Programmpunkte beim Betriebsausflug."}, {"key": "F", "text": "Für den Firmenlauf werden sportliche Mitarbeiter gesucht."}], "bankTitle": "Aussagen", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 7),
    ('hv3', 'Hören', 'Hören, Teil 3', 5, 'Sie hören eine Information der Geschäftsleitung. Wählen Sie für die Aufgaben 32–35 die richtige Lösung A, B oder C.', 'mc', '{"maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 8),
    ('hv4', 'Hören', 'Hören, Teil 4', 4, 'Sie hören fünf Ansagen auf der Mailbox. Wählen Sie für die Aufgaben 36–40 die richtige Lösung A, B oder C.', 'mc', '{"maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 9),
    ('hvs', 'Hören und Schreiben', 'Hören und Schreiben, Telefonnotiz', 15, 'Hören Sie die Nachricht und füllen Sie die Telefonnotiz aus.', 'writing', '{"passages": [{"paragraphs": [{"t": "Telefonnotiz: Fehlende Prospekte", "b": true}, {"t": "Nachricht auf dem Anrufbeantworter von Herrn Städtler:", "b": false}, {"t": "„Guten Tag, hier spricht Herr Städtler, buchstabiert S-T-Ä-D-T-L-E-R. Ich habe kürzlich 180 Prospekte bei Ihnen bestellt. Allerdings sind nur 100 bei uns angekommen. Ich würde darum bitten, die fehlenden 80 Prospekte bis morgen zu liefern. Bitte rufen Sie mich zurück, um die Lieferung zu bestätigen. Sie erreichen mich unter der Telefonnummer 0173 536 47 15. Vielen Dank und auf Wiederhören.“", "b": false}]}], "maxPoints": 9, "availablePoints": 9, "missing": 0, "pointsPerItem": 9, "audio": "telc-b2-m03-hvs.mp3", "audioPlays": 2}'::jsonb, 10),
    ('sb1', 'Sprachbausteine', 'Sprachbausteine, Teil 1', 10, 'Lesen Sie den Text und schließen Sie die Lücken 46–51. Welches Wort aus der Liste a–j passt in welche Lücke?', 'matching', '{"bank": [{"key": "A", "text": "ANSONSTEN"}, {"key": "B", "text": "DAFÜR"}, {"key": "C", "text": "DAHIN"}, {"key": "D", "text": "DAVON"}, {"key": "E", "text": "DEREN"}, {"key": "F", "text": "DESSEN"}, {"key": "G", "text": "ZURÜCK"}, {"key": "H", "text": "WAS"}, {"key": "I", "text": "WIE"}, {"key": "J", "text": "ANBEI"}], "bankTitle": "Wörterliste", "passages": [{"paragraphs": [{"t": "Rücksendung des Arbeitsvertrags und Vorbereitung auf den Arbeitsantritt", "b": true}, {"t": "Sehr geehrte Frau Klingenberg,", "b": false}, {"t": "vielen Dank für die positive Nachricht, bereits zum ersten März bei Ihnen anfangen zu dürfen. Hierüber freue ich mich wirklich sehr. In der Anlage sende ich Ihnen den unterschriebenen Arbeitsvertrag (46). Nun bin ich gespannt auf die zukünftige Arbeit und den ersten Tag an meinem neuen Arbeitsplatz.", "b": false}, {"t": "Aber bis (47) ist ja noch etwas Zeit und deshalb wollte ich Sie fragen, wie ich mich auf meine neue Tätigkeit vorbereiten kann. Vielleicht können Sie mir fachspezifische Internetseiten empfehlen, mit (48) Hilfe ich mich intensiver mit den Produkten vertraut machen kann.", "b": false}, {"t": "Bei dem Vorstellungsgespräch sprachen Sie (49), dass Sie mir die Arbeitskleidung stellen. Benötigen Sie (50) meine Kleider- und Schuhgrößen?", "b": false}, {"t": "Das erforderliche ärztliche Attest vom Gesundheitsamt bringe ich, (51) besprochen, zum Arbeitsantritt mit.", "b": false}, {"t": "Sollten Sie sonst irgendetwas von mir benötigen, können Sie mich natürlich gern kontaktieren.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Philipp Kunz", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 11),
    ('sb2', 'Sprachbausteine', 'Sprachbausteine, Teil 2', 10, 'Lesen Sie den Text und schließen Sie die Lücken 52–57. Welche Lösung (A, B oder C) ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Zahlungserinnerung", "b": true}, {"t": "Sehr geehrter Herr Batic,", "b": false}, {"t": "im Oktober haben wir in Ihrem Firmengebäude an der Heizungsanlage Reparaturarbeiten ausgeführt. Da wir (52) gehört haben, gehen wir davon aus, dass alles zu Ihrer Zufriedenheit war.", "b": false}, {"t": "Allerdings ist bislang für unsere Rechnung Nr. 2008/123 in Höhe von 2.746,- Euro leider keine (53).", "b": false}, {"t": "Für den Fall, dass die Rechnung bei Ihnen verloren gegangen ist, senden wir Ihnen anbei eine Kopie mit der Bitte um (54).", "b": false}, {"t": "Da der Betrag bereits am 31. Oktober (55) war, können wir Ihnen den eingeräumten Skonto von 2% leider nicht mehr (56). Wir bitten um Verständnis.", "b": false}, {"t": "Sollten Sie die Rechnung (57) bezahlt haben, betrachten Sie dieses Schreiben bitte als gegenstandslos.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Ilka Desgrane", "b": false}, {"t": "Heizung und Sanitär Resch", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 12)
) as v(section_id, grp, title, minutes, instruction, format, config, sort)
join tests t on t.level_id = 'telc-b2' and t.slug = 'modell-03'
on conflict (test_id, section_id) do update set "group" = excluded."group", title = excluded.title, minutes = excluded.minutes, instruction = excluded.instruction, format = excluded.format, config = excluded.config, sort = excluded.sort;

insert into items (section_id, item_id, text, options, points, meta, sort)
select s.id, v.item_id, v.text, v.options, v.points, v.meta, v.sort
from (values
    ('lv1', '1', 'Lamia überlegt, ob sie im Vorstellungsgespräch ihre Schwangerschaft erwähnen muss.', null::jsonb, 3, null::jsonb, 0),
    ('lv1', '2', 'Raymond möchte im Internet einen Job finden.', null::jsonb, 3, null::jsonb, 1),
    ('lv1', '3', 'Karl will sich in der Gastronomie selbstständig machen.', null::jsonb, 3, null::jsonb, 2),
    ('lv1', '4', 'Sean ist unsicher, ob er seinen kranken Sohn mit ins Büro nehmen darf.', null::jsonb, 3, null::jsonb, 3),
    ('lv1', '5', 'Ramona interessiert sich für Jobchancen als Reiseverkehrskauffrau.', null::jsonb, 3, null::jsonb, 4),
    ('lv2', '6', 'Im ersten halben Jahr nach Neueinstellung ist kein Urlaub möglich.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('lv2', '7', 'Urlaubsanträge müssen', '[{"key": "A", "text": "durch den Betriebsrat genehmigt werden."}, {"key": "B", "text": "in jedem Fall bewilligt werden."}, {"key": "C", "text": "rechtzeitig im Vorjahr gestellt werden."}]'::jsonb, 3, null::jsonb, 1),
    ('lv2', '8', 'Das Rauchverbot auf dem Firmengelände schließt E-Zigaretten ein.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 2),
    ('lv2', '9', 'Raucher', '[{"key": "A", "text": "erhalten weitere Informationen zu den Raucherbestimmungen in der Personalabteilung."}, {"key": "B", "text": "müssen ihre Pausenzeiten dokumentieren."}, {"key": "C", "text": "sind auch in der Raucherpause bei Unfällen versichert."}]'::jsonb, 3, null::jsonb, 3),
    ('lv3', '10', 'Som: Meine Kinder sind unter der Woche ganztags in der Kita, damit ich Vollzeit arbeiten kann. Jetzt soll ich in den nächsten Wochen samstags ins Büro kommen. Ich habe aber niemanden, der da auf meine Kinder aufpassen kann. Kann der Arbeitgeber das verlangen?', null::jsonb, 3, null::jsonb, 0),
    ('lv3', '11', 'Reinhold: Ich arbeite seit zwölf Jahren 20 Stunden die Woche und würde jetzt gerne, weil die Kinder aus dem Haus sind, meine Arbeitszeit aufstocken und wieder Vollzeit arbeiten. Habe ich ein Recht darauf?', null::jsonb, 3, null::jsonb, 1),
    ('lv3', '12', 'Mandy: Seit zwei Jahren arbeite ich Vollzeit in einem Unternehmen und dieser Job macht mir auch viel Spaß. Aus familiären Gründen würde ich gerne eine dreijährige Auszeit nehmen. Ich überlege, ob ich mir das finanziell leisten kann.', null::jsonb, 3, null::jsonb, 2),
    ('lv3', '13', 'Nici: Ich bekomme jetzt das zweite Kind und werde danach wahrscheinlich erst mal Teilzeit arbeiten. Jetzt habe ich ziemlich große Angst, dass ich in meiner Karriere den Anschluss verpasse. Soll ich vielleicht doch so schnell wie möglich wieder Vollzeit arbeiten?', null::jsonb, 3, null::jsonb, 3),
    ('lv4', '14', 'Bei der Sitzung wird', '[{"key": "A", "text": "das Protokoll der letzten Besprechung geändert."}, {"key": "B", "text": "die Tagesordnung genehmigt."}, {"key": "C", "text": "über Personalthemen gesprochen."}]'::jsonb, 3, null::jsonb, 0),
    ('lv4', '15', 'Einige Mitarbeiter machen Überstunden,', '[{"key": "A", "text": "da andere Kollegen Urlaub machen."}, {"key": "B", "text": "obwohl sie selbst krank sind."}, {"key": "C", "text": "weil viele Kollegen krank sind."}]'::jsonb, 3, null::jsonb, 1),
    ('lv4', '16', 'Herr Meichsner (KM)', '[{"key": "A", "text": "ist Wettbewerber der Firma."}, {"key": "B", "text": "möchte sein Konzept besprechen."}, {"key": "C", "text": "plant eine Rabattaktion im Frühling."}]'::jsonb, 3, null::jsonb, 2),
    ('lv4', '17', 'Die Firma', '[{"key": "A", "text": "besucht die Frühjahrsmesse regelmäßig."}, {"key": "B", "text": "braucht Hilfe bei der Standgestaltung."}, {"key": "C", "text": "lässt gerade Broschüren drucken."}]'::jsonb, 3, null::jsonb, 3),
    ('lv4', '18', 'Persönliche Gegenstände', '[{"key": "A", "text": "können während der Renovierung nicht in der Küche bleiben."}, {"key": "B", "text": "sollen erst am Donnerstag mitgenommen werden."}, {"key": "C", "text": "sollen durch die Hausverwaltung weggeworfen werden."}]'::jsonb, 3, null::jsonb, 4),
    ('lvs1', '19', 'Herr Stiller', '[{"key": "A", "text": "ist mit dem Entwurf der Agentur nicht einverstanden."}, {"key": "B", "text": "möchte, dass Frau Spindler sich einen Entwurf ansieht."}, {"key": "C", "text": "möchte wissen, wer den Entwurf überarbeiten kann."}]'::jsonb, 3, null::jsonb, 0),
    ('lvs1', '20', 'Die Agenturchefin erklärt intern, dass sie', '[{"key": "A", "text": "weitere Änderungen nur gegen Aufpreis macht."}, {"key": "B", "text": "überhaupt keine Fehler gemacht hat."}, {"key": "C", "text": "vorab keine Vorgaben von Herrn Stiller hatte."}]'::jsonb, 3, null::jsonb, 1),
    ('lvs2', 'B', 'Antworten Sie Herrn Stiller im Namen von Monika Holsten.', null::jsonb, 0, '{"points": ["Bedauern über die Unannehmlichkeiten und Bestätigung der Korrektur der vertauschten Namen", "Erklärung bezüglich des vereinbarten Farbschemas", "Hinweis auf die Anzahl der bisherigen Korrekturen und Zusatzkosten für weitere Änderungen", "Bitte um Zustimmung (sein Okay) für die kostenpflichtigen Anpassungen"]}'::jsonb, 0),
    ('hv1', '22', 'Der Geschäftsführer und die Marketingleiterin sprechen über Maßnahmen zur Umsatzsteigerung.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('hv1', '23', 'Die Firma möchte', '[{"key": "A", "text": "ihre Preise drastisch senken."}, {"key": "B", "text": "in Zukunft im Ausland produzieren."}, {"key": "C", "text": "das Verkaufspersonal besser schulen."}]'::jsonb, 3, null::jsonb, 1),
    ('hv1', '24', 'Herr Thoma verkauft Bodenbeläge.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 2),
    ('hv1', '25', 'Frau Lüdeke', '[{"key": "A", "text": "reklamiert einen Schaden am Teppich."}, {"key": "B", "text": "trifft ihre Entscheidung allein aufgrund des Musters."}, {"key": "C", "text": "wundert sich über den Preisunterschied zwischen den beiden Teppichen."}]'::jsonb, 3, null::jsonb, 3),
    ('hv1', '26', 'Ignacio ist Amiras Kollege.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 4),
    ('hv1', '27', 'Die Erzieherin (Amira Herbst)', '[{"key": "A", "text": "arbeitet diese Woche vorübergehend in einer anderen Gruppe."}, {"key": "B", "text": "kann diese Woche keinesfalls den Spätdienst übernehmen."}, {"key": "C", "text": "muss diese Woche dauerhaft zwei Gruppen gleichzeitig betreuen."}]'::jsonb, 3, null::jsonb, 5),
    ('hv2', '28', 'Person 1 (Herr Schmidt und Mia)', null::jsonb, 3, null::jsonb, 0),
    ('hv2', '29', 'Person 2 (Herr 1, Emilia und Herr 2)', null::jsonb, 3, null::jsonb, 1),
    ('hv2', '30', 'Person 3 (Michael und Sabine)', null::jsonb, 3, null::jsonb, 2),
    ('hv2', '31', 'Person 4 (Lena, Ella und Tom)', null::jsonb, 3, null::jsonb, 3),
    ('hv3', '32', 'Das alte Firmenlogo', '[{"key": "A", "text": "ist nicht überall einsetzbar."}, {"key": "B", "text": "passt nicht mehr zum erweiterten Angebot."}, {"key": "C", "text": "wirkt altmodisch und unmodern."}]'::jsonb, 3, null::jsonb, 0),
    ('hv3', '33', 'Das neue Firmenlogo enthält', '[{"key": "A", "text": "den vollständigen Namen des Unternehmens."}, {"key": "B", "text": "weiterhin ein Symbol für Fußbälle."}, {"key": "C", "text": "zwei farbige Elemente."}]'::jsonb, 3, null::jsonb, 1),
    ('hv3', '34', 'Herr Aydin', '[{"key": "A", "text": "wird sich bei der Umstellung Unterstützung von den Mitarbeitern holen."}, {"key": "B", "text": "soll den Mitarbeitern das Logo erst Ende des Jahres vorstellen."}, {"key": "C", "text": "wird die ersten Logo-Entwürfe erst im Sommer sehen."}]'::jsonb, 3, null::jsonb, 2),
    ('hv3', '35', 'Die Einführung des neuen Logos soll', '[{"key": "A", "text": "an einem einzigen Stichtag abgeschlossen sein."}, {"key": "B", "text": "nach erfolgreichem Abschluss gemeinsam gefeiert werden."}, {"key": "C", "text": "nicht länger als zwei Wochen dauern."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '36', 'Waldemar', '[{"key": "A", "text": "trifft die Geschäftspartner an der Produktionshalle."}, {"key": "B", "text": "geht es gesundheitlich nicht gut."}, {"key": "C", "text": "muss seine kranke Tochter von der Schule abholen."}]'::jsonb, 3, null::jsonb, 0),
    ('hv4', '37', 'Jana', '[{"key": "A", "text": "hat den Großauftrag bereits offiziell gemailt."}, {"key": "B", "text": "möchte einen höheren Sonderrabatt aushandeln."}, {"key": "C", "text": "benötigt die Drucker dringend für ihr neues Großraumbüro."}]'::jsonb, 3, null::jsonb, 1),
    ('hv4', '38', 'Erisia', '[{"key": "A", "text": "ist während der Mittagspause ganz alleine am Empfang."}, {"key": "B", "text": "bittet Frau Schmidt, in den Konferenzraum zu kommen."}, {"key": "C", "text": "braucht dringend jemanden zum Dolmetschen."}]'::jsonb, 3, null::jsonb, 2),
    ('hv4', '39', 'Trixi', '[{"key": "A", "text": "fährt selbst mit zur Messe nach Köln."}, {"key": "B", "text": "hat die Hotelzimmer für alle Helfer bereits gebucht."}, {"key": "C", "text": "findet keine preisgünstige Spedition für die Ausstellung."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '40', 'Julius', '[{"key": "A", "text": "darf künftig keine externen Fortbildungen mehr buchen."}, {"key": "B", "text": "erinnert an die strikten Sicherheits- und Rauchregeln bei der Fortbildung."}, {"key": "C", "text": "hat negative Reaktionen der Mitarbeiter zu früheren Seminaren erhalten."}]'::jsonb, 3, null::jsonb, 4),
    ('hvs', '41', 'Dokumentieren Sie die Kundenanfrage:', null::jsonb, 0, '{"points": ["Name des Anrufers (Herr Städtler, S-T-Ä-D-T-L-E-R)", "Telefonnummer (0173 536 47 15)", "Gegenstand der Reklamation (180 Prospekte bestellt, aber nur 100 geliefert)", "Kundenwunsch (Nachlieferung der fehlenden 80 Prospekte bis morgen)", "Zu erledigen (Rückruf zur Bestätigung der Lieferung)"]}'::jsonb, 0),
    ('sb1', '46', '… In der Anlage sende ich Ihnen den unterschriebenen Arbeitsvertrag (46). …', null::jsonb, 0.5, null::jsonb, 0),
    ('sb1', '47', '… Aber bis (47) ist ja noch etwas Zeit und deshalb wollte ich Sie fragen, …', null::jsonb, 0.5, null::jsonb, 1),
    ('sb1', '48', '… fachspezifische Internetseiten empfehlen, mit (48) Hilfe ich mich intensiver …', null::jsonb, 0.5, null::jsonb, 2),
    ('sb1', '49', '… Bei dem Vorstellungsgespräch sprachen Sie (49), dass Sie mir die Arbeitskleidung stellen. …', null::jsonb, 0.5, null::jsonb, 3),
    ('sb1', '50', '… Benötigen Sie (50) meine Kleider- und Schuhgrößen? …', null::jsonb, 0.5, null::jsonb, 4),
    ('sb1', '51', '… ärztliche Attest vom Gesundheitsamt bringe ich, (51) besprochen, zum Arbeitsantritt mit. …', null::jsonb, 0.5, null::jsonb, 5),
    ('sb2', '52', '… Reparaturarbeiten ausgeführt. Da wir (52) gehört haben, gehen wir davon aus, …', '[{"key": "A", "text": "nichts Gegenteiliges"}, {"key": "B", "text": "nur Anderes"}, {"key": "C", "text": "viel Negatives"}]'::jsonb, 0.5, null::jsonb, 0),
    ('sb2', '53', '… Rechnung Nr. 2008/123 in Höhe von 2.746,- Euro leider keine (53). …', '[{"key": "A", "text": "Auszahlung veranlasst"}, {"key": "B", "text": "Einzahlung gemacht"}, {"key": "C", "text": "Zahlung eingegangen"}]'::jsonb, 0.5, null::jsonb, 1),
    ('sb2', '54', '… senden wir Ihnen anbei eine Kopie mit der Bitte um (54). …', '[{"key": "A", "text": "nachfolgenden Betrag"}, {"key": "B", "text": "schnellstmögliche Überweisung"}, {"key": "C", "text": "zeitnahe Korrektur"}]'::jsonb, 0.5, null::jsonb, 2),
    ('sb2', '55', '… Da der Betrag bereits am 31. Oktober (55) war, …', '[{"key": "A", "text": "abgelaufen"}, {"key": "B", "text": "fällig"}, {"key": "C", "text": "verspätet"}]'::jsonb, 0.5, null::jsonb, 3),
    ('sb2', '56', '… den eingeräumten Skonto von 2% leider nicht mehr (56). Wir bitten um Verständnis. …', '[{"key": "A", "text": "gewähren"}, {"key": "B", "text": "leisten"}, {"key": "C", "text": "überreichen"}]'::jsonb, 0.5, null::jsonb, 4),
    ('sb2', '57', '… Sollten Sie die Rechnung (57) bezahlt haben, betrachten Sie dieses Schreiben bitte als gegenstandslos. …', '[{"key": "A", "text": "infolgedessen"}, {"key": "B", "text": "währenddessen"}, {"key": "C", "text": "zwischenzeitlich"}]'::jsonb, 0.5, null::jsonb, 5)
) as v(section_id, item_id, text, options, points, meta, sort)
join tests t on t.level_id = 'telc-b2' and t.slug = 'modell-03'
join sections s on s.test_id = t.id and s.section_id = v.section_id
on conflict (section_id, item_id) do update set text = excluded.text, options = excluded.options, points = excluded.points, meta = excluded.meta, sort = excluded.sort;

