    ('hv3', '32', 'Ein Computer sollte', '[{"key": "A", "text": "nicht mehrmals ein- und ausgeschaltet werden."}, {"key": "B", "text": "nur selten ganz heruntergefahren werden."}, {"key": "C", "text": "von allein in den Ruhemodus schalten."}]'::jsonb, 3, null::jsonb, 0),
    ('hv3', '33', 'Frau Seibert empfiehlt,', '[{"key": "A", "text": "den Entwurfmodus beim Drucken zu verwenden."}, {"key": "B", "text": "immer Recyclingpapier zu benutzen."}, {"key": "C", "text": "Unterlagen für Kunden beidseitig zu bedrucken."}]'::jsonb, 3, null::jsonb, 1),
    ('hv3', '34', 'Frau Seibert findet es wichtig, dass', '[{"key": "A", "text": "die Firma den Müll sorgfältiger trennt."}, {"key": "B", "text": "mehr recycelt wird."}, {"key": "C", "text": "von vornherein weniger Abfall produziert wird."}]'::jsonb, 3, null::jsonb, 2),
    ('hv3', '35', 'Geschäftsreisen', '[{"key": "A", "text": "lassen sich problemlos durch Videokonferenzen ersetzen."}, {"key": "B", "text": "mit der Bahn haben verschiedene Vorteile."}, {"key": "C", "text": "sind teurer, wenn sie umweltfreundlich sind."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '36', 'Rita', '[{"key": "A", "text": "informiert über den günstigen Verkauf alter Firmencomputer."}, {"key": "B", "text": "möchte ihren privaten Computer verkaufen."}, {"key": "C", "text": "sorgt sich um die Finanzierung des Sommerfests."}]'::jsonb, 3, null::jsonb, 0),
    ('hv4', '37', 'Konstantinos Pagonas ruft an, um', '[{"key": "A", "text": "einen Firmenbesuch anzukündigen."}, {"key": "B", "text": "nach dem Weg zur Firma zu fragen."}, {"key": "C", "text": "organisatorische Informationen zur Anreise mitzuteilen."}]'::jsonb, 3, null::jsonb, 1),
    ('hv4', '38', 'Lara Hartmann', '[{"key": "A", "text": "benötigt dringend Belege für das Steuerbüro."}, {"key": "B", "text": "bringt der Kollegin die Reisebelege vorbei."}, {"key": "C", "text": "hat gestern das Steuerbüro angerufen."}]'::jsonb, 3, null::jsonb, 2),
    ('hv4', '39', 'Thomas Barthel', '[{"key": "A", "text": "hat Schwierigkeiten mit seinem eigenen Computer."}, {"key": "B", "text": "kann das aufgetretene Problem per Fernwartung lösen."}, {"key": "C", "text": "soll eine Systemumstellung im Haus vornehmen."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '40', 'Klara Günther', '[{"key": "A", "text": "erinnert an den Abgabetermin für die Urlaubsplanung."}, {"key": "B", "text": "legt die Urlaubsplanung zentral fest."}, {"key": "C", "text": "möchte am 29. November Urlaub nehmen."}]'::jsonb, 3, null::jsonb, 4),
    ('hvs', '41', 'Dokumentieren Sie die Kundenanfrage:', null::jsonb, 0, '{"points": ["Name des Anrufers (Herr Kienzle, K-I-E-N-Z-L-E)", "Telefonnummer (0179 335 36 37)", "Anlass des Anrufs (Angebot für Visitenkartenbestellung mit Premiumpapier)", "Konditionen (100 Stück für 60,99 Euro, Expresslieferung innerhalb von zwei Tagen)", "Zu erledigen (Rückruf zur Bestätigung der Papiersorte)"]}'::jsonb, 0),
    ('sb1', '46', '… geschlossenen Arbeitsvertrag form- und fristgerecht (46) nächstmöglichen Datum. …', null::jsonb, 0.5, null::jsonb, 0),
    ('sb1', '47', '… wird unsere gesamte Familie so bald wie (47) umziehen. …', null::jsonb, 0.5, null::jsonb, 1),
