    ('sb2', '53', '… Hatten Sie schon die Möglichkeit, (53)? …', '[{"key": "A", "text": "das Angebot zu prüfen"}, {"key": "B", "text": "die Chancen zu nutzen"}, {"key": "C", "text": "die Gelegenheit zu bieten"}]'::jsonb, 0.5, null::jsonb, 1),
    ('sb2', '54', '… dass die erwähnte Rabattaktion nur noch bis Ende des Jahres (54). …', '[{"key": "A", "text": "gültig ist"}, {"key": "B", "text": "anerkannt wird"}, {"key": "C", "text": "einlösbar bleibt"}]'::jsonb, 0.5, null::jsonb, 2),
    ('sb2', '55', '… zögern Sie bitte nicht, sich mit uns (55). …', '[{"key": "A", "text": "in Kontakt zu treten"}, {"key": "B", "text": "in Verbindung zu setzen"}, {"key": "C", "text": "zur Verfügung zu stellen"}]'::jsonb, 0.5, null::jsonb, 3),
    ('sb2', '56', '… Unsere Mitarbeiter im Kundenservice (56) Ihnen gerne jederzeit zur Verfügung. …', '[{"key": "A", "text": "sind"}, {"key": "B", "text": "stehen"}, {"key": "C", "text": "stellen"}]'::jsonb, 0.5, null::jsonb, 4),
    ('sb2', '57', '… Wir freuen uns, Sie zukünftig (57) zu können. Mit freundlichen Grüßen …', '[{"key": "A", "text": "bei unseren Kunden besuchen"}, {"key": "B", "text": "mit unseren Kunden begrüßen"}, {"key": "C", "text": "zu unseren Kunden zählen"}]'::jsonb, 0.5, null::jsonb, 5)
) as v(section_id, item_id, text, options, points, meta, sort)
join tests t on t.level_id = 'telc-b2' and t.slug = 'modell-04'
join sections s on s.test_id = t.id and s.section_id = v.section_id
on conflict (section_id, item_id) do update set text = excluded.text, options = excluded.options, points = excluded.points, meta = excluded.meta, sort = excluded.sort;

