-- ================= modell-07 · KANTINE =================
insert into tests (level_id, slug, title, subtitle, blocks, aufgaben, published, sort)
values ('telc-b2', 'modell-07', 'KANTINE', '53 Aufgaben · 125 Minuten',
        '[{"id": "block-lesen", "parts": ["lv1", "lv2", "lv3", "lv4"], "title": "Lesen", "minutes": 45, "hint": "Aufgaben 1–18", "maxPoints": 54, "availablePoints": 54, "missing": 0}, {"id": "block-lesen-schreiben", "parts": ["lvs1", "lvs2"], "title": "Lesen und Schreiben", "minutes": 20, "hint": "Aufgaben 19–20 und Beschwerde", "maxPoints": 13, "availablePoints": 13, "missing": 0}, {"id": "block-hoeren", "parts": ["hv1", "hv2", "hv3", "hv4"], "title": "Hören", "minutes": 20, "hint": "Aufgaben 22–40", "maxPoints": 57, "availablePoints": 57, "missing": 0}, {"id": "block-hoeren-schreiben", "parts": ["hvs"], "title": "Hören und Schreiben", "minutes": 5, "hint": "Aufgabe 41 und Telefonnotiz", "maxPoints": 9, "availablePoints": 9, "missing": 0}, {"id": "block-sb", "parts": ["sb1", "sb2"], "title": "Sprachbausteine", "minutes": 35, "hint": "Aufgaben 46–57", "maxPoints": 6, "availablePoints": 6, "missing": 0}]'::jsonb, 53, true, 7)
on conflict (level_id, slug) do update set title = excluded.title, subtitle = excluded.subtitle, blocks = excluded.blocks, aufgaben = excluded.aufgaben, sort = excluded.sort;

insert into sections (test_id, section_id, "group", title, minutes, instruction, format, config, sort)
select t.id, v.section_id, v.grp, v.title, v.minutes, v.instruction, v.format, v.config, v.sort
from (values
    ('lv1', 'Lesen', 'Lesen, Teil 1', 10, 'Lesen Sie die Aufgaben 1–5 und die Informationen a–h. Welche Information passt zu welcher Situation?', 'matching', '{"bank": [{"key": "A", "text": "Den Arbeitsplatz produktiv gestalten: Die richtige Atmosphäre am Arbeitsplatz ist für die effektive Erledigung der Aufgaben unerlässlich. Gerlinde Strauß beschreibt, wie man mit den richtigen Möbeln, Dekoartikeln, Licht, Ordnung am Arbeitsplatz und vielem mehr die eigene Umgebung so gestaltet, dass man die Zeit am Arbeitsplatz gerne und erfolgreich verbringt."}, {"key": "B", "text": "Ohne Selbstdisziplin geht es nicht: Die Arbeit von zu Hause aus erfordert ein hohes Maß an Selbstdisziplin und die Fähigkeit des Selbstmanagements. Privates und Arbeit sollten strikt getrennt werden. Doch wie funktioniert das am besten? Helga Brinkmann hat einen Ratgeber für Arbeitskräfte herausgegeben, deren Unternehmen diese Form der Arbeit anbieten."}, {"key": "C", "text": "Hobbys im Lebenslauf richtig einsetzen: Ausbildung und Qualifikation sind in erster Linie wichtig, wenn man den Lebenslauf eines Bewerbers liest. Doch auch, welche Hobbys eine Person hat, kann Auskunft darüber geben, ob sie zum Unternehmen passt oder nicht. Lesen Sie hier wichtige Tipps und Tricks für eine überzeugende Bewerbung."}, {"key": "D", "text": "Was unsere Körpersprache über uns verrät: Ob beim Vorstellungsgespräch, bei wichtigen Verhandlungen mit Kunden oder am ersten Arbeitstag – unsere Körpersprache gibt immer Auskunft darüber, wie wir uns gerade fühlen, z. B. angespannt oder selbstsicher. Lernen Sie in unserem Seminar, wie Sie Körpersprache wirksam einsetzen und wie Sie Ihr Gegenüber einschätzen können."}, {"key": "E", "text": "Der erste Arbeitstag in der neuen Firma: So klappt es mit den Kolleginnen. Anspannung ist ganz normal: Beim Start im neuen Job ist es wichtig, gut vorbereitet zu sein. Im folgenden Artikel von Irene Miller finden Sie eine Checkliste mit den wichtigsten Punkten, die Sie beachten sollten, damit der Einstieg gelingt."}, {"key": "F", "text": "Angemessene Bezahlung? Jeder möchte für seine Leistung fair bezahlt werden. Doch in vielen Berufsfeldern haben die Arbeitnehmer das Gefühl, unterbezahlt zu sein. Die Folge davon sind Motivationsverlust und Zweifel daran, ob man wirklich den richtigen Beruf gewählt hat. Lesen Sie hier, wie Sie erfolgreich Gehaltsverhandlungen führen."}, {"key": "G", "text": "Körperliche Folgen von Stress: Nicht jeder Stress macht krank. Es gibt auch positiven Stress, der die Leistungsfähigkeit eines Menschen erhöht. Wer aber unter Daueranspannung steht und körperliche Symptome wie Bluthochdruck, Magenbeschwerden oder eine anhaltende innere Anspannung spürt, muss etwas ändern. Wie, das erfahren Sie im neusten Buch von Harald Erhard."}, {"key": "H", "text": "Frauen verdienen immer noch zu wenig: Europaweit ist das Ziel der Gleichstellung noch längst nicht erreicht. Man denke hier nur an die nach wie vor ungleiche Bezahlung von Männern und Frauen und an die Besetzung von Stellen in der Führungsetage. Deutschland liegt bei diesem Vergleich noch immer auf einem der letzten Plätze."}], "bankTitle": "Informationen", "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 0),
    ('lv2', 'Lesen', 'Lesen, Teil 2', 15, 'Lesen Sie die Texte und die Aufgaben 6 bis 9. Entscheiden Sie, welche Lösung am besten passt.', 'mc', '{"passages": [{"paragraphs": [{"t": "Willkommensmappe für neue Mitarbeiterinnen und Mitarbeiter", "b": true}, {"t": "Essen in der Kantine", "b": true}, {"t": "Unser Unternehmen arbeitet an sieben Tagen rund um die Uhr im Drei-Schicht-System. Deshalb steht auch unsere Kantine, die für die Mitarbeiterverpflegung sorgt, täglich 24 Stunden zur Verfügung. Um unnötige Wartezeiten in der Mittagszeit zu vermeiden, wurden in Abstimmung mit dem Betriebsrat aber folgende Essenszeiten für die einzelnen Abteilungen festgelegt: Während das Personal aus der Produktion und dem Lager in der ersten Gruppe von 12.00 bis 13.00 Uhr eine warme Mahlzeit zu sich nehmen kann, folgen die Mitarbeiterinnen und Mitarbeiter der Verwaltung in der zweiten Gruppe von 13.00 bis 14.00 Uhr.", "b": false}, {"t": "Außerdem können die Mitarbeitenden jederzeit frisch zubereitete Snacks oder kleine Mahlzeiten wie Suppen oder Nudelgerichte aus den in der Kantine aufgestellten Automaten entnehmen. Darüber hinaus befindet sich dort eine Mikrowelle, in der Sie mitgebrachte Speisen erwärmen können. Zusätzliche Automaten für kalte und warme Getränke befinden sich auf jeder Etage in unserem Firmengebäude.", "b": false}]}, {"paragraphs": [{"t": "Willkommensmappe für neue Mitarbeiterinnen und Mitarbeiter", "b": true}, {"t": "Arbeitsunfall und Berufsgenossenschaft (BG)", "b": true}, {"t": "Mit dem Arbeitsantritt in unserem Unternehmen sind Sie als Arbeitnehmer*in automatisch gesetzlich unfallversichert.", "b": false}, {"t": "Der Träger dieser Unfallversicherung ist die Berufsgenossenschaft, deren Aufgaben in erster Linie darin bestehen, Arbeits- und Wegeunfälle, Berufskrankheiten sowie arbeitsbedingte Gesundheitsgefahren zu vermeiden. Das wird gewährleistet, indem regelmäßig Kontrollen der Arbeitssicherheit durch die Berufsgenossenschaft stattfinden. Bei diesen Kontrollen sind unsere Mitarbeiter*innen des Qualitätsmanagements mit vor Ort.", "b": false}, {"t": "Sollte dennoch ein Unglücksfall eintreten, übernimmt die Berufsgenossenschaft sämtliche Kosten für Heilbehandlungen und Schadensersatzzahlungen. Dafür muss von Ihnen folgendes Prozedere eingehalten werden: Nach einem Arbeitsunfall wird zunächst der Ersthelfer oder die Ersthelferin informiert. Je nach Schwere des Unfalls wird ein Rettungswagen dazu gerufen. Ob mit oder ohne Krankenhausaufenthalt, müssen Sie aber in jedem Fall von einem Durchgangsarzt untersucht werden. Gleichzeitig sind wir als Arbeitgeber verpflichtet, den Unfall der Berufsgenossenschaft zu melden. Damit setzt der Prozess ein, dass die Berufsgenossenschaft Ihre Behandlung und deren Kosten übernimmt. Damit für Sie als Arbeitnehmer*in keine finanziellen Probleme entstehen, zahlt die Berufsgenossenschaft Ihnen den Lohn ab der siebten Woche der Arbeitsunfähigkeit weiter.", "b": false}, {"t": "Damit es aber gar nicht erst so weit kommt, führen wir regelmäßig Schulungen zur Arbeitssicherheit durch. Diese beinhalten auf der einen Seite Einweisungen zum korrekten Tragen der Schutzkleidung und auf der anderen Seite konkrete Anweisungen zur richtigen Bedienung der Maschinen.", "b": false}]}], "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 1),
    ('lv3', 'Lesen', 'Lesen, Teil 3', 10, 'Lesen Sie die Situationen 10–13 und die Beiträge a–f aus einem Online-Forum. Welcher Beitrag passt zu welcher Situation?', 'matching', '{"bank": [{"key": "A", "text": "Stefan: Kaum jemandem gelingt es, 45 Jahre durchgehend so ein hohes Gehalt zu verdienen, dass er später die Höchstrente bekommt. Das liegt schon allein daran, dass man während der Ausbildung und in den ersten Berufsjahren weniger verdient."}, {"key": "B", "text": "Jana: Auch Firmen helfen, für die Zukunft vorzusorgen, denn man kann gar nicht früh genug damit anfangen. Erkundige dich bei deinem Arbeitgeber, ob eine betriebliche Altersvorsorge angeboten wird. Wenn man dann später Rentner ist, bekommt man eine zusätzliche Rente."}, {"key": "C", "text": "Antje: Wenn man mindestens fünf Jahre versicherungspflichtig beschäftigt war, hat man Anspruch auf die gesetzliche Rente. Dabei spielt es keine Rolle, ob man Teilzeit oder Vollzeit gearbeitet hat. Es gibt aber noch Unterschiede zwischen Ost und West."}, {"key": "D", "text": "Jonas: Man hat das Recht, früher als mit 67 Jahren in Rente zu gehen, aber man muss Abschläge in Kauf nehmen. Im Moment sind das für jeden Monat, den man weniger arbeitet, 0,3 Prozent weniger. Man muss sich das genau ausrechnen, ob man sich das leisten kann."}, {"key": "E", "text": "Jörg: Für alle, die nach 1964 geboren sind, gilt, dass sie bis 67 Jahre arbeiten müssen. Außer, wenn man mit 65 schon 45 Beitragsjahre nachweisen kann, also Jahre, in denen man in die Rentenversicherung eingezahlt hat."}, {"key": "F", "text": "Lia: Wenn man jung ist, sollte man sein Leben doch erst einmal genießen. Über Alter und Krankheit kann man sich immer noch Gedanken machen. Wer weiß, ob es später, wenn wir so weit sind, überhaupt noch eine Rente geben wird."}, {"key": "X", "text": "Keine Antwort passt"}], "bankTitle": "Forumsbeiträge", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 2),
    ('lv4', 'Lesen', 'Lesen, Teil 4', 10, 'Lesen Sie das Protokoll und die Aufgaben 14 bis 18. Entscheiden Sie, welche Lösung am besten passt.', 'mc', '{"passages": [{"paragraphs": [{"t": "Protokoll 15.01.20XX, 10.00 bis 11.30 Uhr", "b": true}, {"t": "Sitzungsraum 205, Ort: Hauptstraße 27, 99099 Erfurt", "b": false}, {"t": "Anwesende: Jakob Müller (JM, Geschäftsleitung), Friedrich Döring (FD, Vertrieb), Karl Altmann (KA, Buchhaltung und Finanzen), Peter Bischoff (PB, Produktion), Karsten Hinz (KH, Logistik), Jana Bartsch (JB, Personal), Beate Fritsch (BF, Marketing), Jonas Stoll (JS, IT-Abteilung)", "b": false}, {"t": "Sitzungsleitung: Jakob Müller", "b": false}, {"t": "Protokollant: Jonas Stoll", "b": false}, {"t": "Tagesordnungspunkte:", "b": true}, {"t": "1. Begrüßung und Tagesordnung", "b": false}, {"t": "2. Kosteneinsparungen", "b": false}, {"t": "3. Lagebericht Produktion", "b": false}, {"t": "4. Kündigung des Betriebsarztes", "b": false}, {"t": "5. Betriebliche Altersvorsorge", "b": false}, {"t": "6. Sonstiges", "b": false}, {"t": "TOP 1 Begrüßung und Tagesordnung", "b": true}, {"t": "JM heißt die Kolleg*innen zur heutigen Besprechung herzlich willkommen und bestätigt die Anwesenheit aller eingeladenen Teilnehmer*innen. Danach erkundigt JM sich, ob noch zusätzliche Themen protokollarisch aufgenommen werden sollen. Hierzu gibt es keine Kommentare und damit gilt die Tagesordnung als genehmigt.", "b": false}, {"t": "TOP 2 Kosteneinsparungen", "b": true}, {"t": "Wie JM darstellt, hat sich der Markt im Vergleich zum Vorjahr stark verändert. In diesem Zusammenhang müssen deshalb Kostenstrukturen neu überdacht werden. Es wird vorgeschlagen, die administrativen Kosten zu senken, da es hier Einsparungspotenzial gibt. Im Vorfeld zu dieser Besprechung wurde JB bereits von der Geschäftsleitung beauftragt, eine exakte Kostenübersicht zu erstellen und Vorschläge zur Kostenreduzierung vorzulegen. JB legt dar, dass die in der Firmenzentrale eingehenden Anrufe auf ein externes Call-Center umgeleitet werden könnten. Verschiedene Kostenvoranschläge wurden hierfür auch schon eingeholt. Die Firma tele-info scheint unseren Ansprüchen am besten gerecht zu werden. Deshalb sollten Vertragsverhandlungen aufgenommen und zeitgleich Schulungspläne für die Call-Center-Mitarbeiter*innen ausgearbeitet werden, um ihnen die Organisationsstruktur des Unternehmens so schnell wie möglich näherzubringen, damit die Arbeit ohne Verzögerung aufgenommen werden kann. Durch die so gewonnene Zeitersparnis am Empfang können Mitarbeiter*innen von dort flexibler eingesetzt werden und zum Beispiel zusätzlich den für das Unternehmen wichtigen Konferenzbereich und die Gästebetreuung übernehmen. JM stimmt den Vorschlägen zu und bittet um Umsetzung der weiteren Schritte.", "b": false}, {"t": "TOP 3 Lagebericht Produktion", "b": true}, {"t": "PB merkt an, dass auch in seiner Abteilung eine Kostenreduzierung möglich wäre, indem unausgewogene Lagerungen von Material und Rohstoffen vermieden werden. Das Lagerungsmanagement ist optimierbar, d.h., dass sowohl zu hohe als auch zu niedrige Lagermengen vermieden werden müssen, da sie zu unnötigen Kosten führen. Im Fall von Überbeständen muss neue Lagerfläche geschaffen werden und im Fall von Unterbeständen kann es zu kurzfristigen Produktionsausfällen kommen. JM beauftragt PB, sich umgehend zusammen mit KH mit dieser Thematik auseinanderzusetzen und zur nächsten Sitzung konkrete Zahlen und Vorschläge vorzulegen.", "b": false}, {"t": "TOP 4 Kündigung des Betriebsarztes", "b": true}, {"t": "Mit Bedauern teilt die Geschäftsleitung mit, dass unser Betriebsarzt die Firma zum Jahresende verlässt, da er eine eigene Praxis eröffnen will. Aus diesem Grund hat sich die Firma entschlossen, die Ersthelferausbildung zu forcieren, damit bei kleineren Verletzungen, die im Produktionsablauf immer wieder auftreten können, sofort eingegriffen werden kann. Ärztliche Unterstützung bekommen wir ab nächstem Jahr von der Allgemeinärztlichen Praxis Dr. Mertens. Die Kontaktdaten werden bekannt gegeben.", "b": false}, {"t": "TOP 5 Betriebliche Altersvorsorge", "b": true}, {"t": "Seit einem Jahr bietet die Firma den Mitarbeiter*innen an, in eine betriebliche Zusatzrente zu investieren. Bisher wird dieses Angebot aber nur von wenigen Kolleg*innen genutzt. Deshalb werden erneut alle Abteilungsleiter*innen darauf hingewiesen, in ihren Abteilungen über diese Möglichkeit der Altersvorsorge aufzuklären. Interessierte Mitarbeiter*innen können in der Personalabteilung genauere Informationen erhalten. Zusätzlich bietet die Versicherungsgesellschaft immer donnerstags eine gesonderte Sprechstunde an, zu der man sich aber anmelden muss.", "b": false}, {"t": "TOP 6 Sonstiges", "b": true}, {"t": "Die Mitarbeiter*innen werden gebeten, im Intranet abzustimmen, ob die Firma in diesem Jahr für alle Kolleg*innen entweder einen eintägigen Betriebsausflug oder ein Sommerfest organisieren soll. Für den Betriebsausflug könnten dann auch gleich Vorschläge unterbreitet werden. Die Abstimmung muss bis zum 31.03. erfolgen, damit für das Organisationskomitee noch ausreichend Zeit für die Planung bleibt.", "b": false}]}], "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 3),
    ('lvs1', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 1', 5, 'Lesen Sie die E-Mail und die Aufgaben 19 und 20. Entscheiden Sie, welche Lösung am besten passt.', 'mc', '{"passages": [{"paragraphs": [{"t": "Beschwerde über fehlerhafte Rechnung", "b": true}, {"t": "Sehr geehrte Frau Hoffner,", "b": false}, {"t": "wir haben Ihre Lieferung erhalten und sind mit allen Artikeln absolut zufrieden. Leider muss ich Sie darauf hinweisen, dass die Rechnung einige Unstimmigkeiten beinhaltet: Zunächst wurden statt 100 Stück Pinsel Größe M 200 Stück berechnet. Außerdem wurden 20 Töpfe roter Farbe berechnet. Wir hatten aber grüne Farbe bestellt und geliefert bekommen, die preislich niedriger liegt. Wir bitten Sie, dies zu korrigieren. Des Weiteren waren wir überrascht, dass unser üblicher Rabatt von 10 % in dieser Rechnung nicht gewährt wurde. Das ist wahrscheinlich ein Versehen. Wir bitten um Berichtigung der Rechnung und erneute Zusendung.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Karl Schmidt (Firma Meier)", "b": false}]}], "maxPoints": 6, "availablePoints": 6, "missing": 0, "pointsPerItem": 3}'::jsonb, 4),
    ('lvs2', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 2', 15, 'Antworten Sie auf die Beschwerde.', 'writing', '{"passages": [{"paragraphs": [{"t": "Arbeitsanweisung von Ihrer Vorgesetzten:", "b": true}, {"t": "Hallo, ich habe heute die E-Mail von Herrn Schmidt erhalten. Bitte kümmern Sie sich darum und antworten Sie dem Kunden höflich. Die Firma Meier ist ein langjähriger Kunde von uns. Wir können es uns nicht leisten, ihn zu verlieren. Schreiben Sie ihm bitte von unserem Computerproblem und wie wir es gelöst haben. Natürlich bekommt er den Rabatt wie gewohnt. Vielen Dank, Anna Hoffner.", "b": false}]}], "maxPoints": 7, "availablePoints": 7, "missing": 0, "pointsPerItem": 7}'::jsonb, 5),
    ('hv1', 'Hören', 'Hören, Teil 1', 6, 'Sie hören drei Gespräche. Zu jedem Gespräch gibt es zwei Aufgaben. Entscheiden Sie, ob die Aussage richtig oder falsch ist und welche Antwort am besten passt.', 'mc', '{"maxPoints": 18, "availablePoints": 18, "missing": 0, "pointsPerItem": 3}'::jsonb, 6),
    ('hv2', 'Hören', 'Hören, Teil 2', 5, 'Sie hören vier Personen über Fortbildungen sprechen. Welcher der Aussagen a–f passt zu welcher Person?', 'matching', '{"bank": [{"key": "A", "text": "Das Lernen hört im Arbeitsleben nie auf."}, {"key": "B", "text": "Die Firma sollte regelmäßig arbeitsplatzbezogene Schulungen organisieren."}, {"key": "C", "text": "Es ist sinnvoll, Fortbildungen an unterschiedlichen Tagen anzubieten."}, {"key": "D", "text": "Weiterbildungen sind nur mit hohem finanziellem Aufwand möglich."}, {"key": "E", "text": "Fortbildungen kosten vor allem wertvolle Arbeitszeit."}, {"key": "F", "text": "Nicht alle Schulungen müssen im Betrieb stattfinden."}], "bankTitle": "Aussagen", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 7),
    ('hv3', 'Hören', 'Hören, Teil 3', 4, 'Sie hören eine Information für Mitarbeiterinnen und Mitarbeiter. Wählen Sie bei den Aufgaben 32 bis 35 die richtige Lösung.', 'mc', '{"maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 8),
    ('hv4', 'Hören', 'Hören, Teil 4', 5, 'Sie hören fünf kurze Telefongespräche oder Ansagen. Zu jedem Text gibt es eine Aufgabe. Wählen Sie die richtige Lösung.', 'mc', '{"maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 9),
    ('hvs', 'Hören und Schreiben', 'Hören und Schreiben', 15, 'Hören Sie die Nachricht und füllen Sie die Telefonnotiz aus.', 'writing', '{"passages": [{"paragraphs": [{"t": "Telefonnotiz: Reparatur bzw. Austausch des Kopierers", "b": true}, {"t": "Nachricht auf dem Anrufbeantworter von Anna Schulze (Firma Shell):", "b": false}, {"t": "„Mein Name ist Anna Schulze, Firma Shell am Apparat. Ich habe mir Ihren defekten Kopierer angesehen. Es liegt ein größeres Problem mit der Elektronik vor, das man nur in unserer Werkstatt beheben kann. Vor Ort konnte ich ihn nicht wieder zum Laufen bringen. Ein Austausch würde ca. vier Wochen dauern, da wir derzeit Probleme mit dem Lieferanten haben. Wenn Sie sich für eine Reparatur entscheiden, müssten wir noch ein Ersatzteil bestellen. Das würde insgesamt ca. zwei Werktage dauern. Leider haben wir zurzeit kein Leihgerät, das wir Ihnen zur Verfügung stellen können. Die Reparatur würde mein Kollege machen, da ich nächste Woche im Urlaub bin. Die Frage ist nun, ob wir den Kopierer austauschen oder reparieren sollen. Rufen Sie mich bitte bis morgen zurück. Schulze, S-C-H-U-L-Z-E. Meine Telefonnummer ist 0160 335 101 8.“", "b": false}]}], "maxPoints": 9, "availablePoints": 9, "missing": 0, "pointsPerItem": 9, "audio": "telc-b2-m07-hvs.mp3", "audioPlays": 2}'::jsonb, 10),
    ('sb1', 'Sprachbausteine', 'Sprachbausteine, Teil 1', 10, 'Lesen Sie den Text und schließen Sie die Lücken 46–51. Welches Wort aus der Liste a–j passt in welche Lücke?', 'matching', '{"bank": [{"key": "A", "text": "AM"}, {"key": "B", "text": "AUßERDEM"}, {"key": "C", "text": "BIS"}, {"key": "D", "text": "DESHALB"}, {"key": "E", "text": "IHNEN"}, {"key": "F", "text": "IM"}, {"key": "G", "text": "MICH"}, {"key": "H", "text": "MIT"}, {"key": "I", "text": "NÄMLICH"}, {"key": "J", "text": "ZU"}], "bankTitle": "Wörterliste", "passages": [{"paragraphs": [{"t": "Kündigung", "b": true}, {"t": "Sehr geehrte Frau Schneider,", "b": false}, {"t": "ich teile Ihnen mit, dass ich mein Arbeitsverhältnis zum 31.03. fristgerecht kündige, weil mein Mann am 01.05. (46) einer neuen Tätigkeit in Süddeutschland beginnt und die ganze Familie im April dorthin umziehen wird. Dieser Schritt ist für mich nicht leicht, ich war (47) immer sehr gerne hier tätig.", "b": false}, {"t": "Ich habe noch einige Fragen (48) den Formalitäten: Bitte teilen Sie mir mit, bis wann und wo ich den Firmenwagen abgeben und ob ich die Daten von meinem Firmenlaptop löschen soll. (49) bitte ich Sie um ein Zwischenzeugnis, da ich mich jetzt schon um eine neue Stelle bewerben möchte. Würden Sie mir bitte auch mitteilen, ob mir mein Arbeitszeugnis am letzten Arbeitstag ausgehändigt oder (50) Nachhinein zugeschickt wird?", "b": false}, {"t": "Ich bedanke (51) für die interessante Zeit in Ihrem Unternehmen und die fruchtbare Zusammenarbeit.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Melanie Sommer", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 11),
    ('sb2', 'Sprachbausteine', 'Sprachbausteine, Teil 2', 10, 'Lesen Sie den Text und schließen Sie die Lücken 52–57. Welche Lösung passt am besten?', 'mc', '{"passages": [{"paragraphs": [{"t": "Fehlerhafte Lieferung", "b": true}, {"t": "Sehr geehrter Herr Sonneberg,", "b": false}, {"t": "vielen Dank für die schnelle Bearbeitung unserer Bestellung vom 29.10.", "b": false}, {"t": "Für die Einrichtung unserer Pausenräume hatten wir zehn Sitzeckbänke in der Farbe Weiß bestellt. (52) Sie zehn Tische und für jede Sitzeinheit drei Stühle in der gleichen Farbe liefern.", "b": false}, {"t": "Leider entspricht die Lieferung nicht (53). Zwei von den zehn Sitzeckbänken wurden in Braun geliefert. Von den 30 Stühlen haben ebenfalls fünf die falsche Farbe. Wir bitten Sie, die reklamierten Möbelstücke (54).", "b": false}, {"t": "Außerdem weisen zwei Tische Kratzer an der Oberfläche auf. Wir würden die Tische trotzdem behalten, wenn Sie dafür einen entsprechenden (55). Könnten Sie uns hierfür (56)?", "b": false}, {"t": "Wir bitten um (57). Für Rückfragen stehen wir Ihnen jederzeit zur Verfügung.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Sonja Schmidt", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 12)
) as v(section_id, grp, title, minutes, instruction, format, config, sort)
join tests t on t.level_id = 'telc-b2' and t.slug = 'modell-07'
on conflict (test_id, section_id) do update set "group" = excluded."group", title = excluded.title, minutes = excluded.minutes, instruction = excluded.instruction, format = excluded.format, config = excluded.config, sort = excluded.sort;

insert into items (section_id, item_id, text, options, points, meta, sort)
select s.id, v.item_id, v.text, v.options, v.points, v.meta, v.sort
from (values
    ('lv1', '1', 'Kurt sucht einen Job und braucht Anregungen für seine Unterlagen.', null::jsonb, 3, null::jsonb, 0),
    ('lv1', '2', 'Juliette arbeitet gerne, fühlt sich aber oft erschöpft.', null::jsonb, 3, null::jsonb, 1),
    ('lv1', '3', 'Peter ist vor seinem Start im neuen Unternehmen nervös.', null::jsonb, 3, null::jsonb, 2),
    ('lv1', '4', 'Katharina ist wegen des niedrigen Verdienstes in ihrer Branche frustriert.', null::jsonb, 3, null::jsonb, 3),
    ('lv1', '5', 'Carlos braucht Tipps für seine Tätigkeit im Homeoffice.', null::jsonb, 3, null::jsonb, 4),
    ('lv2', '6', 'Die Kantine ist immer geöffnet.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('lv2', '7', 'Die Mitarbeiterinnen und Mitarbeiter', '[{"key": "A", "text": "bekommen in der Kantine keine Getränke."}, {"key": "B", "text": "können nachts in der Kantine essen."}, {"key": "C", "text": "müssen mittags oft sehr lange anstehen."}]'::jsonb, 3, null::jsonb, 1),
    ('lv2', '8', 'Alle Mitarbeitenden müssen für eine Arbeitsunfallversicherung sorgen.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 2),
    ('lv2', '9', 'Nach einem Arbeitsunfall', '[{"key": "A", "text": "muss man sich einem Durchgangsarzt vorstellen."}, {"key": "B", "text": "schickt die BG einen Arzt oder Rettungswagen."}, {"key": "C", "text": "übernimmt die BG sofort die Gehaltsfortzahlungen."}]'::jsonb, 3, null::jsonb, 3),
    ('lv3', '10', 'Torsten: „Wir hatten neulich im Büro eine Diskussion darüber, ab wann man in Rente gehen kann. Ich dachte immer, man muss bis 67 arbeiten. Aber meine Kollegin meinte, dass sie zwei Jahre früher in Rente gehen kann. Geht das ohne Weiteres?“', null::jsonb, 3, null::jsonb, 0),
    ('lv3', '11', 'Marion: „Meine Rente wird ja nicht so berauschend sein, vor allem, weil ich wegen meiner zwei Kinder einige Jahre nicht oder nur Teilzeit gearbeitet habe. Es ist ja wohl schon so, dass ich dafür jetzt irgendwie bestraft werde, oder?“', null::jsonb, 3, null::jsonb, 1),
    ('lv3', '12', 'Petra: „Mein Mann geht in zwei Jahren in Rente. Ich müsste noch vier Jahre arbeiten. Wir haben uns überlegt, dass wir zusammen in Rente gehen und noch viele gemeinsame Jahre mit verschiedenen Aktivitäten erleben wollen. Welche Folgen hätte das?“', null::jsonb, 3, null::jsonb, 2),
    ('lv3', '13', 'Leni: „Ich bin ja noch jung und denke überhaupt noch nicht an die Rente. Aber es wird ja immer wieder gesagt, dass die normale Rente irgendwann nicht mehr ausreichen wird. Was kann ich denn jetzt schon für später tun?“', null::jsonb, 3, null::jsonb, 3),
    ('lv4', '14', 'Bei der Besprechung', '[{"key": "A", "text": "müssen weitere Themen besprochen werden."}, {"key": "B", "text": "sind alle Mitarbeiter*innen des Unternehmens anwesend."}, {"key": "C", "text": "wird die Tagesordnung angenommen."}]'::jsonb, 3, null::jsonb, 0),
    ('lv4', '15', 'Um Kosten zu sparen,', '[{"key": "A", "text": "sollen einige Empfangsmitarbeiter*innen in ein Call-Center wechseln."}, {"key": "B", "text": "werden die Aufgaben der Mitarbeitenden am Empfang neu festgelegt."}, {"key": "C", "text": "wird der Empfang demnächst geschlossen."}]'::jsonb, 3, null::jsonb, 1),
    ('lv4', '16', 'Der Lagerbestand muss', '[{"key": "A", "text": "an die Produktion angepasst werden."}, {"key": "B", "text": "dauerhaft ausgebaut werden."}, {"key": "C", "text": "kurzfristig reduziert werden."}]'::jsonb, 3, null::jsonb, 2),
    ('lv4', '17', 'Der Betriebsarzt wird', '[{"key": "A", "text": "mit Dr. Mertens zusammenarbeiten."}, {"key": "B", "text": "zukünftig selbstständig arbeiten."}, {"key": "C", "text": "zum Jahresende entlassen."}]'::jsonb, 3, null::jsonb, 3),
    ('lv4', '18', 'Die betriebliche Altersvorsorge', '[{"key": "A", "text": "kann bei einem vereinbarten Termin besprochen werden."}, {"key": "B", "text": "nehmen viele Mitarbeiter*innen an."}, {"key": "C", "text": "wird neu in der Firma eingeführt."}]'::jsonb, 3, null::jsonb, 4),
    ('lvs1', '19', 'Herr Schmidt', '[{"key": "A", "text": "hat falsche Waren vom Lieferanten erhalten."}, {"key": "B", "text": "meldet eine unvollständige Sendung."}, {"key": "C", "text": "weist auf falsche Posten in der Zahlungsaufforderung hin."}]'::jsonb, 3, null::jsonb, 0),
    ('lvs1', '20', 'Die Rechnung', '[{"key": "A", "text": "hat 100 Pinsel nicht aufgeführt."}, {"key": "B", "text": "ist ohne Preisnachlass ausgestellt worden."}, {"key": "C", "text": "wurde an einen falschen Adressaten geschickt."}]'::jsonb, 3, null::jsonb, 1),
    ('lvs2', 'B', 'Antworten Sie Herrn Schmidt im Namen von Anna Hoffner.', null::jsonb, 0, '{"points": ["Bedauern und Entschuldigung für die fehlerhafte Rechnungsstellung ausdrücken", "Erklärung der Ursache (Computerfehler, der inzwischen behoben wurde)", "Korrektur der Rechnungsposten (Pinselmenge und grüne Farbe) sowie Bestätigung des 10%-Rabatts", "Ankündigung der berichtigten Rechnung und Wertschätzung der langjährigen Partnerschaft"]}'::jsonb, 0),
    ('hv1', '22', 'Der Teamleiter zeigt einer neuen Mitarbeiterin ihren Arbeitsplatz.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('hv1', '23', 'Frau Blume', '[{"key": "A", "text": "darf ihre Schichten selbst bestimmen."}, {"key": "B", "text": "wird ab sofort im Kundenservice eingesetzt."}, {"key": "C", "text": "wird die Kunden nur per E-Mail betreuen."}]'::jsonb, 3, null::jsonb, 1),
    ('hv1', '24', 'Die Auszubildenden handeln einen Kompromiss mit der Abteilungsleiterin aus.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 2),
    ('hv1', '25', 'Die beiden Auszubildenden', '[{"key": "A", "text": "dürfen gleichzeitig den Stand verlassen."}, {"key": "B", "text": "dürfen keine Kundengespräche führen."}, {"key": "C", "text": "wollen die Konkurrenz beobachten."}]'::jsonb, 3, null::jsonb, 3),
    ('hv1', '26', 'Frau Leutner bestellt telefonisch neue Möbel.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 4),
    ('hv1', '27', 'Die Möbelfirma', '[{"key": "A", "text": "bietet nur kostenpflichtige Montage der Ware."}, {"key": "B", "text": "hat Lieferzeiten von mindestens zwei Wochen."}, {"key": "C", "text": "kann Möbelstücke in verschiedenen Ausführungen herstellen."}]'::jsonb, 3, null::jsonb, 5),
    ('hv2', '28', 'Sprecherin 1 meint, dass Schulungen nicht zwingend im eigenen Betrieb abgehalten werden müssen.', null::jsonb, 3, null::jsonb, 0),
    ('hv2', '29', 'Sprecherin 2 betont, dass lebenslanges Lernen und ständige Weiterbildung im Beruf unverzichtbar sind.', null::jsonb, 3, null::jsonb, 1),
    ('hv2', '30', 'Sprecher 3 plädiert dafür, dass das Unternehmen gezielte Schulungen für den Arbeitsalltag anbietet.', null::jsonb, 3, null::jsonb, 2),
    ('hv2', '31', 'Sprecher 4 findet flexible Termine und unterschiedliche Tage für Schulungsangebote wichtig.', null::jsonb, 3, null::jsonb, 3),
    ('hv3', '32', 'Die Kita plant,', '[{"key": "A", "text": "ausschließlich Auszubildende einzusetzen."}, {"key": "B", "text": "die Mitarbeitenden zu motivieren."}, {"key": "C", "text": "neues Personal zu rekrutieren."}]'::jsonb, 3, null::jsonb, 0),
    ('hv3', '33', 'In jedem Team', '[{"key": "A", "text": "arbeiten Erzieher*innen gleichen Alters."}, {"key": "B", "text": "können Springer*innen eingesetzt werden."}, {"key": "C", "text": "sind vier Betreuer*innen tätig."}]'::jsonb, 3, null::jsonb, 1),
    ('hv3', '34', 'Die Kitaleitung', '[{"key": "A", "text": "führt bereits Vorstellungsgespräche."}, {"key": "B", "text": "hat die Teams zusammengestellt."}, {"key": "C", "text": "organisiert Workshops für die Mitarbeitenden."}]'::jsonb, 3, null::jsonb, 2),
    ('hv3', '35', 'Die Mitarbeitenden sollen', '[{"key": "A", "text": "an einem Kochkurs teilnehmen."}, {"key": "B", "text": "besser zusammenarbeiten."}, {"key": "C", "text": "ihre Persönlichkeit stärken."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '36', 'Jan', '[{"key": "A", "text": "kennt bereits die Kosten für die Farben."}, {"key": "B", "text": "kontaktiert den Techniker."}, {"key": "C", "text": "kümmert sich um die Farbauswahl."}]'::jsonb, 3, null::jsonb, 0),
    ('hv4', '37', 'Die Firma Software Solution', '[{"key": "A", "text": "liefert in fünf bis sechs Stunden ihre Kassen."}, {"key": "B", "text": "möchte mit dem Supermarkt einen Termin vereinbaren."}, {"key": "C", "text": "überwacht die Sicherheit im Kassenbereich."}]'::jsonb, 3, null::jsonb, 1),
    ('hv4', '38', 'Gabi soll', '[{"key": "A", "text": "den Operationsplan ändern."}, {"key": "B", "text": "Herrn Sommer anrufen."}, {"key": "C", "text": "mit dem Hausarzt über die Blutwerte sprechen."}]'::jsonb, 3, null::jsonb, 2),
    ('hv4', '39', 'Anna', '[{"key": "A", "text": "bestellt italienisches Essen für alle."}, {"key": "B", "text": "organisiert eine Aktivität für das Team."}, {"key": "C", "text": "will nur mit Claudia ins Kino gehen."}]'::jsonb, 3, null::jsonb, 3),
    ('hv4', '40', 'Stefan berichtet, dass', '[{"key": "A", "text": "der Lieferant erkrankt ist."}, {"key": "B", "text": "die Kolleg*innen streiken wollen."}, {"key": "C", "text": "nicht pünktlich geliefert werden kann."}]'::jsonb, 3, null::jsonb, 4),
    ('hvs', '41', 'Dokumentieren Sie das Serviceangebot:', null::jsonb, 0, '{"points": ["Name der Anruferin (Anna Schulze, S-C-H-U-L-Z-E, Firma Shell)", "Telefonnummer (0160 335 101 8)", "Schadensbefund (Größeres Elektronikproblem, Behebung nur in Werkstatt möglich)", "Optionen (Austausch dauert ca. 4 Wochen; Reparatur dauert ca. 2 Werktage, Ersatzteil nötig; kein Leihgerät verfügbar)", "Zu erledigen (Bis morgen zurückrufen und Entscheidung mitteilen: Reparatur oder Austausch)"]}'::jsonb, 0),
    ('sb1', '46', '… weil mein Mann am 01.05. (46) einer neuen Tätigkeit in Süddeutschland beginnt …', null::jsonb, 0.5, null::jsonb, 0),
    ('sb1', '47', '… ich war (47) immer sehr gerne hier tätig. …', null::jsonb, 0.5, null::jsonb, 1),
    ('sb1', '48', '… Ich habe noch einige Fragen (48) den Formalitäten …', null::jsonb, 0.5, null::jsonb, 2),
    ('sb1', '49', '… (49) bitte ich Sie um ein Zwischenzeugnis …', null::jsonb, 0.5, null::jsonb, 3),
    ('sb1', '50', '… am letzten Arbeitstag ausgehändigt oder (50) Nachhinein zugeschickt wird? …', null::jsonb, 0.5, null::jsonb, 4),
    ('sb1', '51', '… Ich bedanke (51) für die interessante Zeit …', null::jsonb, 0.5, null::jsonb, 5),
    ('sb2', '52', 'Lücke 52', '[{"key": "A", "text": "Dafür mussten"}, {"key": "B", "text": "Daher konnten"}, {"key": "C", "text": "Dazu sollten"}]'::jsonb, 0.5, null::jsonb, 0),
    ('sb2', '53', 'Lücke 53', '[{"key": "A", "text": "unserem Angebot"}, {"key": "B", "text": "unseren Vorschriften"}, {"key": "C", "text": "unserer Bestellung"}]'::jsonb, 0.5, null::jsonb, 1),
    ('sb2', '54', 'Lücke 54', '[{"key": "A", "text": "gleich zurückzuschicken"}, {"key": "B", "text": "schnellstmöglich auszutauschen"}, {"key": "C", "text": "sofort zu reparieren"}]'::jsonb, 0.5, null::jsonb, 2),
    ('sb2', '55', 'Lücke 55', '[{"key": "A", "text": "Aufpreis anbieten"}, {"key": "B", "text": "Preisnachlass gewähren"}, {"key": "C", "text": "Rabatt fordern"}]'::jsonb, 0.5, null::jsonb, 3),
    ('sb2', '56', 'Lücke 56', '[{"key": "A", "text": "ein Angebot unterbreiten"}, {"key": "B", "text": "ein Gutachten erstellen"}, {"key": "C", "text": "eine Empfehlung geben"}]'::jsonb, 0.5, null::jsonb, 4),
    ('sb2', '57', 'Lücke 57', '[{"key": "A", "text": "baldige Bezahlung"}, {"key": "B", "text": "gleichzeitige Stornierung"}, {"key": "C", "text": "umgehende Antwort"}]'::jsonb, 0.5, null::jsonb, 5)
) as v(section_id, item_id, text, options, points, meta, sort)
